        exit(1);
    }

    iface_1.set_output_interface(&iface_2);
    iface_2.set_output_interface(&iface_1);

    std::thread thread_iface_1(iface_1);
    std::thread thread_iface_2(iface_2);

    thread_iface_1.join();
    thread_iface_2.join();

    return 0;
}

