        static bool make_daemon(void) {
            int pid = 0;

            if (pid = fork()) {
                exit(0);    //是父进程，结束父进程
            } else if (pid < 0) {
                //exit(1);    //fork失败，退出
                return false;
            }

            //是第一子进程，后台继续执行
            setsid();//第一子进程成为新的会话组长和进程组长

            //并与控制终端分离
            if (pid = fork()) {
                exit(0);    //是第一子进程，结束第一子进程
            } else if (pid < 0) {
                //exit(1);    //fork失败，退出
                return false;
            }

            //是第二子进程，继续
            //第二子进程不再是会话组长
            for (int i = 0; i < NOFILE; ++i) { //关闭打开的文件描述符
                ::close(i);
            }

            //chdir("/tmp");//改变工作目录到/tmp
            umask(0);//重设文件创建掩模
            return true;
        }

