        bool isAutoRun() {
            return false;
        }

        bool restart(int delay = 3) {
            // 只允许调用一次
            static std::atomic<bool> is_called(false);

            if (is_called) {
                return false;
            }

            is_called = true;
            newInstance(delay);
            close();
            return true;
        }

        // 新开实例
