void TIM0_UP_IRQHandler() //40kHz
{
	static dword tick = 0;

	if (delayTimer >= 25)
		delayTimer -= 25;
	else
		delayTimer = 0;

	if (diskIfTimerFlag)
		diskIfTimer += 25;

	tick++;
	if (tick >= 400) // 100Hz
	{
		tick = 0;

		static dword tick2 = 0;

		tick2++;
		if (tick2 == 100) // 1Hz
		{
			tick2 = 0;
			timer_flag_1Hz++;
		}

		disk_timerproc();
		timer_flag_100Hz++;
	}

	//---------------------------------------------------

	TIM_ClearITPendingBit(TIM0, TIM_IT_Update);
}

void DelayUs(dword delay)
{
	word prevValue = TIM0->CNT;
	delay++;

	while (delay) {
		if (TIM0->CNT != prevValue) {
			prevValue = TIM0->CNT;
			delay--;
		}
	}

	WDT_Kick();
}

void DelayMs(dword delay)
{
	delayTimer = delay * 1000;
	while (delayTimer)
		WDT_Kick();
}

