dword prevEIC_ICR = 0;
dword nesting = 0;

void portENTER_CRITICAL()
{
	if (nesting == 0) {
		dword temp = EIC->ICR & 3;
		EIC->ICR &= ~3;
		prevEIC_ICR = temp;
	}

	nesting++;
}

void portEXIT_CRITICAL()
{
	if (nesting) {
		nesting--;

		if (nesting == 0) {
			EIC->ICR |= prevEIC_ICR;
		}
	}
}

