int main(int argc , char** argv)
{
        if(argc < 3)
        {
                printf("Not Enough Parameters .\n");
                return 0;
        }
        DataSetFileName = argv[1];
        generationCounter = NBR_GEN * atoi(argv[2])  ;
        srand(time(NULL));

        GeneticAlgorithm(NBR_GEN,20,0.15,15);



        return 0;
}

