enum State_enum 
{
    CLI_COMMAND_UNKNOWN     =   0x00,
    CLI_COMMAND_HEADER_01   =   0x01,
    CLI_COMMAND_HEADER_02   =   0x02,
    CLI_COMMAND_OPTYPE      =   0x03,
    CLI_COMMAND_DATA_LENGTH =   0x04,
