    point2d_t p0 = point2d_t(10, 10);
    point2d_t p1 = point2d_t(0, 20);
    point2d_t p2 = point2d_t(30, 30);
    point2d_t p3 = point2d_t(50, 20);
    point2d_t p4 = point2d_t(40, 0);
    point2d_t p5 = point2d_t(20, 0);
