    greek_gods=greek_gods->add(new Link{"Mars"});
    greek_gods=greek_gods->add(new Link{"Poseidon"});

    Link* p = greek_gods->find("Mars");
    if(p) p->value="Ares";

    Link* p2 = norse_gods->find("Zeus");
    if(p2)
    {
        if(norse_gods!=p2) norse_gods=p2;
