__int128 mul(__int128 a,__int128 b,__int128 n){
	__int128 r = 0; a %= n;
	__int128 t;
	static __int128 h = 4294967295;
	if(!b) return r;
	if(t = (b&h)){
		r += a*t;
		if(r >= n) r%=n;
	}
	a = (a << 32) % n;
	if(a >= n) a %= n;
	b>>=32;
