bool isprime(__int128 n){
	if(n % 2 == 0 || n < 2) return n == 2;
	mt19937 rd(time(NULL));
	__int128 u = n-1,t = 0;
	for(;!(u&1);u>>=1) t++;
	for(int i=0;i<9;i++){
		__int128 a = powmo(rd()%n,u,n);
		if(a == 0 || a == n-1 || a == 1) continue;
		for(int j=0;j<t;j++){
			a = mul(a,a,n);
			if(a == 1) return false;
			if(a == n-1) break;
		}
		if(a == n-1) continue;
		return false;
	}
	return true;
}

__int128 rho(__int128 n,int c){
	__int128 x,y;
	x = y = 0;
	while(true){
		x = mul(x,x,n) + c;
		if(x >= n) x -= n;
		x = mul(x,x,n) + c;
		if(x >= n) x -= n;
		y = mul(y,y,n) + c;
		if(y >= n) y -= n;
		__int128 d = x-y;
		if(d < 0) d = -d;
		__int128 g = gcd(d,n);
		if(g != 1) return g;
	}
}

void factor(__int128 n){
