OSErr Executor::HandToHand(GUEST<Handle> *hp)
{
    Handle nh;
    Size s;
    OSErr err;

    if(!*hp)
    {
        warning_unexpected("hp = %p", hp);
        /*-->*/ return nilHandleErr;
    }

    s = GetHandleSize(*hp);
    if((err = MemError()))
        /*-->*/ return (err);

    nh = NewHandle(s);
    if((err = MemError()))
        /*-->*/ return (err);

    BlockMove(**hp, *nh, s);
    *hp = nh;
    return noErr;
}

OSErr Executor::PtrToHand(const void* p, GUEST<Handle> *h, LONGINT s)
{
    Handle nh;
    OSErr err;

    nh = NewHandle(s);
    if((err = MemError()))
        return (err);
    BlockMove(p, *nh, s);
    if((err = MemError()))
        return (err);
    *h = nh;
    return (noErr);
}

OSErr Executor::PtrToXHand(const void* p, Handle h, LONGINT s)
{
    OSErr err;

    /*
 * DO *NOT* use ReallocateHandle here.  It will fail if the handle is locked.
 */
    SetHandleSize(h, s);
    if((err = MemError()))
        return (err);
    BlockMove(p, *h, s);
    if((err = MemError()))
        return (err);
    return (noErr);
}

OSErr Executor::HandAndHand(Handle h1, Handle h2)
{
    Size s1 = GetHandleSize(h1), s2 = GetHandleSize(h2);
    OSErr err;

    SetHandleSize(h2, s1 + s2);
    if((err = MemError()))
        return (err);
    BlockMove(*h1, *h2 + s2, s1);
    if((err = MemError()))
        return (err);
    return (noErr);
}

OSErr Executor::PtrAndHand(const void* p, Handle h, LONGINT s1)
{
