OSErr Executor::WriteParam() /* IMII-382 */
{
    INTEGER rn;
    SysParmType sp;
    LONGINT count;
    OSErr err, err2;

    err = prWrErr;
    if(openparam(out(rn)) == noErr)
    {
        sp.valid = LM(SPValid);
        sp.aTalkA = LM(SPATalkA);
        sp.aTalkB = LM(SPATalkB);
        sp.config = LM(SPConfig);
        sp.portA = LM(SPPortA);
        sp.portB = LM(SPPortB);
        sp.alarm = LM(SPAlarm);
        sp.font = LM(SPFont);
        sp.kbdPrint = (short)(LM(SPKbd) << 8) | (LM(SPPrint) & 0xff);
        sp.volClik = (short)(LM(SPVolCtl) << 8) | (LM(SPClikCaret) & 0xff);
        sp.misc = LM(SPMisc2);
        count = sizeof(sp);
        if(FSWrite(rn, inout(count), &sp) == noErr && count == sizeof(sp))
            err = noErr;
        deriveglobals();
        ROMlib_beepedonce = false;
        err2 = FSClose(rn);
        if(err == noErr)
            err = err2;
    }
    return err;
}

void Executor::Enqueue(QElemPtr e, QHdrPtr h)
{
    GUEST<QElemPtr> *qpp;

    for(qpp = (GUEST<QElemPtr> *)&h->qHead; *qpp && *qpp != e;
        qpp = (GUEST<QElemPtr> *)*qpp)
        ;
    if(!*qpp)
    {
        e->evQElem.qLink = 0;
        if(h->qTail)
            h->qTail->evQElem.qLink = e;
        else
            h->qHead = e;
        h->qTail = e;
    }
}

OSErr Executor::Dequeue(QElemPtr e, QHdrPtr h)
{
    GUEST<QElemPtr> *qpp;       // ### HORRIBLE REINTERPRET-CASTING CODE OBFUSCATION....
    OSErr retval;

    retval = qErr;
    for(qpp = (GUEST<QElemPtr> *)&h->qHead; *qpp && *qpp != e;
        qpp = (GUEST<QElemPtr> *)*qpp)
        ;
    if(*qpp)
    {
        *qpp = e->evQElem.qLink;
        if(h->qTail == e)
            h->qTail = (qpp == (GUEST<QElemPtr> *)&h->qHead) ? nullptr : (QElemPtr)qpp;
        retval = noErr;
    }
    return retval;
}



