void Executor::Delay(LONGINT n, GUEST<LONGINT> *ftp) /* IMII-384 */
{
    if(n > 0)
    {
        TMTask tm;
        shouldbeawake = false;

        tm.tmAddr = (ProcPtr)&ROMlib_wakeup;
        InsTime((QElemPtr)&tm);

        //      fprintf (stderr, "p");
