		{
			unsigned char* out = static_cast<unsigned char*>(buf);
			unsigned char** pout = out != NULL ? &out : NULL;

			int result = i2d_X509_NAME(ptr().get(), pout);

			throw_error_if(result < 0);

			return result;
		}
