{
  Memory_Map::const_iterator itr;
  map<std::string, unsigned int>::const_iterator fmap_itr;
  char from_type_str[20];
  char to_type_str[20];

  vector<idiom>::const_iterator i_itr;

  fclose(out);

  out = fopen (KnobMmapFile.Value().c_str(), "w");  

