      for (map<unsigned long, graph>::iterator itr=thread_graphs.begin(); itr != thread_graphs.end(); ++itr)
	{
	  (*itr).second.save_to_subgraph(gr, i);
	  i++;
	}
      save_idioms (gr);
      fprintf (gr, "}\n");
    }

