// common types
typedef std::vector<uint8_t> bytes_t;

// a sharedptr, so i can pass an istream around without
// worrying about who owns it.
typedef std::shared_ptr<std::istream> stream_ptr;
typedef std::shared_ptr<bytes_t> bytes_ptr;

// memory stream from memory 
class imemstream : std::streambuf, public std::istream {
    std::streampos _size;
public:
    imemstream(uint8_t* base, size_t size) : _size(size),
        std::istream(static_cast<std::streambuf*>(this))
    {
        char* p(reinterpret_cast<char*>(base));
        this->setg(p, p, p + size);
    }
protected:
    std::streampos seekoff(std::streamoff off, std::ios_base::seekdir dir,
        std::ios_base::openmode which = std::ios_base::in | std::ios_base::out)
    {
        if (dir == std::ios_base::cur)
            setg(eback(), gptr() + off, egptr());
        else if (dir == std::ios_base::end)
            setg(eback(), egptr() + off, egptr());
        else if (dir == std::ios_base::beg)
            setg(eback(), eback() + off, egptr());
        return gptr() - eback();
    }
    std::streampos seekpos(std::streampos sp, std::ios_base::openmode which = std::ios_base::in | std::ios_base::out)
    {
        if (sp < 0 || sp > _size)
            return -1;
        return seekoff(sp, std::ios_base::beg, which);
    }
};

// simple hex printer
template<typename T>
std::string str_hex(const T& value)
{
    std::stringstream str;
    str << std::hex << std::setfill('0') << std::setw(sizeof(T::value_type) * 2);;
    for (const auto& val : value)
    {
        if (sizeof(T::value_type) == 1)
            str << static_cast<uint16_t>(val);
        else
            str << val;
    }
    return str.str();
}

#ifdef IDB_ZLIB_COMPRESSION_SUPPORT

// zlib rec
#define CHUNK 16384

int zlib_decompress(stream_ptr& source, uint64_t size, bytes_ptr& dest)
{
    int ret;
    unsigned have;
    z_stream strm;
    uint8_t in[CHUNK];
    uint8_t out[CHUNK];
    uint32_t count = 0;
    uint64_t position = 0;

    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = 0;
    strm.next_in = Z_NULL;

    ret = inflateInit(&strm);
    if (ret != Z_OK) return ret;

    do 
    {
        if (position >= size)
            break;

        count = static_cast<uint32_t>(std::min(uint64_t(CHUNK), size - position));
        source->read(reinterpret_cast<char*>(in), count);
        position += count;

        strm.next_in = in;
        strm.avail_in = count;

        do 
        {
            strm.avail_out = CHUNK;
            strm.next_out = out;
            ret = inflate(&strm, Z_NO_FLUSH);

            if (ret == Z_STREAM_ERROR)
            {
                inflateEnd(&strm);
                throw std::exception("zlib decompression fail");
            }

            switch (ret)
            {
            case Z_NEED_DICT:
                ret = Z_DATA_ERROR;
            case Z_DATA_ERROR:
            case Z_MEM_ERROR:
                inflateEnd(&strm);
                return ret;
            }
            have = CHUNK - strm.avail_out;
            dest->insert(dest->end(), out, out + have);

        } while (strm.avail_out == 0);
    }
    while (ret != Z_STREAM_END);

    inflateEnd(&strm);
    return ret == Z_STREAM_END ? Z_OK : Z_DATA_ERROR;
}

#endif

// create vector from `n`  invocations of `f`
template<typename T, typename FN>
std::vector<T> getvec(int n, FN f)
{
    std::vector<T> v;
    while (n--)
        v.push_back(f());
    return v;
}

