    MemBlockI16 input;
    MemBlockF output;

    input.init(rows,cols);
    output.init(rows,cols);

    input.at(0,0) = bp.getBits();

    // check coarse alone
    calibrator.m_Gf.at(0,0) = 0.0;
    calibrator.processFrameRow(input, output, 0);
    BOOST_CHECK_CLOSE(output.at(0,0), idealOffset + k1 * (8.0f - k2), smallPercent);

