inline float norm(Descriptor& pts1, Descriptor& pts2, int size) {
	float result = .0;

	for ( int i = 0 ; i < size; i++ ) {
		result += ( pts1[ i ] - pts2[ i ] ) * ( pts1[ i ] - pts2[ i ] );
	}

	return result;
}

