			  values[n][m] = num;
			 m = m+1;
			}
		//n++;
	}

int frames = (n+1)/20;
inFile.close();


//----------------------------------------------------------------------------------------------


//Calculating Joint Distances...
float dist[frames][5];
for (int fd=0; fd<frames; fd++)
{
  int r0 = (2 + 20*(fd))-1;
