for (int ft=0; ft<frames; ft++)
{
 int r0 = (2 + 20*(ft))-1;
 int r1 = (4 + 20*(ft))-1;
 int r2 = (8 + 20*(ft))-1;
 int r3 = (12 + 20*(ft))-1;
 int r4 = (16 + 20*(ft))-1;
 int r5 = (20 + 20*(ft))-1;

