  goal_map[1].add(start_x + 200, start_y - 200, start_yaw);
  goal_map[1].add(start_x + 200, start_y - 200, start_yaw,
                  11); // Move: スタートゾーン -> Wait: スタートスイッチ
  goal_map[1].restart();

  int TOWEL_FES_POSITION_Y = start_y + 2730;
  goal_map[2].add(start_x, start_y, start_yaw,
