    SVL_DLLPRIVATE sal_Bool ImpGetTimeOutput( double fNumber,
                       sal_uInt16 nIx,
                       String& OutString );
    SVL_DLLPRIVATE sal_Bool ImpGetDateTimeOutput( double fNumber,
