      delete _mesh;
      _mesh = mesh;
      _currentLevel = level;
    }
  }

  ~LeveledMesh() {
    delete _mesh;
#ifdef JAVA_CODE
  super.dispose();
#endif

  }

  int getVertexCount() const {
    return _mesh->getVertexCount();
  }

  const Vector3D getVertex(int i) const {
    return _mesh->getVertex(i);
  }

