	//srand( time(NULL));
	Handle1 root;
	Handle2 two;
	Handle3 thr;
	root.add(&two);
	root.add(&thr);
	thr.setNext(&root);
	for (int i = 0 ; i < 10 ; i++){
		root.handle(i);
		cout << "\n";
	}
}

