struct xi_nub_ctx
{
    string app_name;
    string user_name;
    string home_path;
    string profile_path;
    void *user_data;
};

struct xi_nub_agent
{
    xi_nub_ctx *ctx;
    vector<string> args;
    xi_nub_platform_desc listen_sock;
    vector<xi_nub_ch> ch;
};

