    value[root] += delta;
    if (value[root])  return 1;
    // need to delete this element, it is now zero!
    if (!is_list && (num_elements < tree2list))
        Tree2List();

    long oldroot = root;
    if (is_list)
        root = nodes.RemoveListRoot(root);
    else
        root = nodes.RemoveTreeRoot(root);
