}QUA;

void init();/*初始化函数*/
bool getqua(QUA *qua);		/*获取一个四元式*/
int isnums(char *val);	/*检测字符串是否是数字串 0 标识符 1整型数串 2浮点数串*/
void makeleaf(DAGNODE *n, char val[]);/*构造叶子结点*/
void makenode(DAGNODE *n, char op[], int left, int right);/*构造中间结点*/
