}
/*初始化函数*/
void init()
{
	if ((fp = fopen("code.txt", "r")) == NULL)
	{
		printf("the code file is not existed."); exit(0);
	}
}
/*获取一个四元式*/
bool getqua(QUA *qua)
{
	int t;
	if (feof(fp)) { fclose(fp); return false; }
