                _shm = _shm == (char*)-1 ? NULL : _shm;
                if (_shm) {
                        for (int i = 0; i < SIZE; ++i)
                                _shm[i] = 0;
                }
        }
        char *shm() {return _shm;}
        virtual ~Shm() {
                shmdt(_shm);
                shmctl(shmid, IPC_RMID, NULL);
        }
private:
        char *_shm;
        int shmid;
};


static bool _quit = false;
extern "C" {static void quit(int sig) {_quit = true;}}


extern "C" int main(int argc, char *argv[])
{
        if (argc < 3)
                return 0;
        Shm sh;
        char *shm = sh.shm();
        if (shm == NULL) {
                syslog(LOG_CRIT, "shm fail");
                return -1;
        }
        const unsigned int val = strtoul(argv[2], NULL, 10);
        char shadow[SIZE] = {0};
        struct sigaction sa;
        sa.sa_handler = quit;
        sigfillset(&sa.sa_mask);
        sa.sa_flags = SA_RESTART;
        sigaction(SIGINT, &sa, NULL);
        sigaction(SIGTERM, &sa, NULL);
        while (!_quit) {
                timespec t0 = {0};
                clock_gettime(CLOCK_MONOTONIC_COARSE, &t0);
                *shm = 0;
                const pid_t child = fork();
                if (child == -1) {
                        return 0;
                } else if (child == 0) {
                        char **progv = (char**)argv + 1;
                        return execv(progv[0], progv);
                } else {
                        syslog(LOG_NOTICE, "forked child %d", child);
                        while (!_quit) {
                                int status;
                                if (waitpid(child, &status, WNOHANG) > 0) {
                                        if (WIFSIGNALED(status))
                                                break;
                                        else if (WIFEXITED(status))
                                                _quit = true;
                                }
                                timespec t;
                                clock_gettime(CLOCK_MONOTONIC_COARSE, &t);
                                bool b = true;
                                for (int i = 1; i <= *shm; ++i)
                                        b &= shm[i] != shadow[i];
                                if (b) {
                                        t0.tv_sec = t.tv_sec;
                                        for (int i = 1; i <= *shm; ++i)
                                                shadow[i] = shm[i];
                                } else if (val && t.tv_sec - t0.tv_sec > val) {
                                        syslog(LOG_NOTICE, "child %d hangs",
                                               child);
                                        kill(child, SIGKILL);
                                        waitpid(-1, NULL, 0);
                                        break;
                                }
                                sleep(2);
                        }
                }
        }
        return 0;
}

