  contents.heap_allocated = false;
  block block(contents);
  iterator* iter = block.newiterator(bytewisecomparator());
  iter->seektofirst();
  assert_true(!iter->valid());
  iter->seektolast();
  assert_true(!iter->valid());
  iter->seek("foo");
  assert_true(!iter->valid());
  delete iter;
}

