template <typename ...Types, std::size_t ...I>
inline void set_tuple_result(lua_State* const L,
  std::tuple<Types...> const& t, std::index_sequence<I...> const) noexcept(
    noexcept(swallow{(set(L, std::get<I>(t)), 0)...})
