>
set(lua_State* const L, C&& m)
{
  lua_createtable(L, 0, m.size());

  auto const cend(m.cend());

  for (auto i(m.cbegin()); i != cend; ++i)
  {
    set(L, i->first);
    set(L, i->second);

    lua_rawset(L, -3);
  }

  return 1;
}

