double trim_double_to_precision(double value, unsigned precision);

int main()
{
    double bin = 0;
    double d;
    for (d = 127; d <= 1025; d++) {
        double t = trim_double_to_precision(d, 7);
        if (t == bin) {
            printf(" %.17g", d);
        }
        else {
            int exp;
            frexp(d, &exp);
            bin = t;
            printf("\nexp = %d, bin = %.17g: %.17g", exp, bin, d);
        }
    }
    return 0;
}
