namespace NoiseBox
{
    enum Param
    {
        P_ADDAMT,
        P_MULAMT,
        P_ADDFREQ,
        P_MULFREQ,
        P_NUM
    };

    struct EffectData
    {
        struct Data
        {
            float p[P_NUM];
            float addcount;
            float addnoise;
            float mulcount;
            float mulnoise;
            Random random;
        };
        union
        {
            Data data;
            unsigned char pad[(sizeof(Data) + 15) & ~15]; // This entire structure must be a multiple of 16 bytes (and and instance 16 byte aligned) for PS3 SPU DMA requirements
        };
