bool Image::GetOffsetFromChipPath (const char * filepath, int &x_offset, int &y_offset) {
  char *path = NULL;
  path = strdup ( filepath );

  char *dir = NULL;
  dir = dirname ( path );

  char *coords = NULL;
  coords = basename ( dir );

  int val = -1;
  x_offset = 0;
  y_offset = 0;
  bool success = false;
  val = sscanf ( coords, "X%d_Y%d", &x_offset, &y_offset );
  if (val == 2) {
    success = true;
  }
  if (path)
     free (path);
  return success;
}

