      //int minK = 0;
      //int maxK = 0;
      // for(frame=0;frame<raw->frames;frame++) {
      k += frameStart*raw->frameStride;
      for ( frame=frameStart;frame<frameEnd;frame++ )
      {
        if ( frame == frameStart || ( raw->image[k] > max ) )
