// Status word. 64-bits wide (struct instead of union)
    struct status_word_union {
        uint8_t  busybit  : 1 ;
        uint64_t priority : 56;
        uint8_t  head     : 7 ;  // Supports at most 128 processors

      // The order of fields is significant
      explicit status_word_union() : busybit(0), priority(0), head(0) {}
      static status_word_union from_u64(uint64_t v) {
        status_word_union w;
        w.busybit  = static_cast<uint8_t>(v & UINT64_C(1));
        w.priority = static_cast<uint64_t>((v >> 1) & UINT64_C(0x000FFFFFFFFFFFFF));
        w.head     = static_cast<uint8_t>((v >> 57) & UINT64_C(0x7F));
        return w;
      }
      uint64_t to_u64() const {
        return (static_cast<uint64_t>(busybit) & UINT64_C(1))
             | (static_cast<uint64_t>(priority) & UINT64_C(0x000FFFFFFFFFFFFF)) << 1
             | (static_cast<uint64_t>(head) & UINT64_C(0x7F)) << 57;
      }
    };

  status_word_union word;
  word.busybit  = is_busy;   // Not busy
  word.priority = prio;
  word.head     = nullary_head;
  status_word.store(word.to_u64());
}

// Sets busy bit and returns the old status word
auto set_busy_bit() -> status_word_union {
  status_word_union word;
  word.busybit = 1u; // I'm going to be busy
  word = status_word_union::from_u64(status_word.fetch_or(word.to_u64()));
  return word;
}

// Update the head field while preserving all other fields
auto cas_head(status_word_union word, uint8_t newHead) -> bool {
  uint64_t expected = word.to_u64();
  auto word2 = word;
  word2.head = newHead; // Update only the head field
  return status_word.compare_exchange_weak(expected, word2.to_u64());
}

auto load() -> status_word_union {
  return status_word_union::from_u64(status_word.load());
}

