template <typename T>
T &read(uint8_t *&p)
{
    auto *ptr = (T *)p;
    p += sizeof(T);

    return *ptr;
}

uint32_t readULEB128(uint8_t *&p)
{
    uint32_t result = 0;
    uint32_t shift = 0;
    while (true)
    {
        uint8_t byte = (*p);
        ++p;
        result |= (byte & 0b01111111) << shift;
        if ((byte & 0b10000000) == 0)
            break;
        shift += 7;
    }

    return result;
}

int32_t readLEB128(uint8_t *&p)
{
    size_t size = 32;

    int32_t result = 0;
    int32_t shift = 0;

    uint8_t byte;
    do
    {
        byte = (*p);
        ++p;
        result |= (byte & 0b01111111) << shift;
        shift += 7;
    } while ((byte & 0b10000000) != 0);

    if ((shift < size) && (byte & 0b10000000))
        result |= (~0 << shift);

    return result;
}

std::string readString(uint8_t *&p)
{
    auto nameSize = readULEB128(p);

    auto str = std::string((char *)p, nameSize);

    p += nameSize;

    return str;
}

float readFloat(uint8_t *&p)
{
    auto v = *(float *)p;
    p += 4;
    return v;
}

template <typename T>
std::vector<T> readVector(uint8_t *&p)
{
    auto v = std::vector<T>{};

    auto vectorSize = readULEB128(p);
    while (vectorSize > 0)
    {
        auto item = T::read(p);
        v.push_back(item);

        --vectorSize;
    }

    return v;
}

uint8_t readOPCode(uint8_t *&p)
{
    auto opcode = *p;
    ++p;

