    if (!lisp_style || !rank)
      o << label;
    if (rank) {
      o << '(';
      word_spacer sp;
      if (lisp_style)
        o << sp << label;
      for (const_iterator i = begin(), e = end(); i!=e; ++i) {
        o << sp;
        (*i)->print(o, lisp_style);
      }
      o << ')';
    }
    return GENIOGOOD;
  }

  template <class O, class Writer>
  void print_writer(O& o, Writer const& w, bool lisp_style = true) const
