FORCE_INLINE static int npy_get_msb(uint64_t unum)
{
    // FUTURE OP: This is just leading zero count
    // return 64 - _lzcnt_u64(unum);
    int depth_limit = 0;
    while (unum >>= 1) {
        depth_limit++;
    }
    return depth_limit;
}

