// For one byte strings
FORCE_INLINE static bool
STRING_LT(const unsigned char* c1, const unsigned char* c2, size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        if (c1[i] != c2[i]) {
            return c1[i] < c2[i];
        }
    }
    return false;
}

//---------------------------------
// Assumes Py_UCS4
// Assumes int is 32bits
FORCE_INLINE static bool
STRING_LT(const uint32_t* c1, const uint32_t* c2, size_t len)
{
    size_t lenunicode = len / 4;

    for (size_t i = 0; i < lenunicode; ++i) {
        if (c1[i] != c2[i]) {
            return c1[i] < c2[i];
        }
    }
    return false;
}

// NOTE: This routine may not be useful
// It will sort an opaque amount of data
FORCE_INLINE static bool
STRING_LT(const char* s1, const char* s2, size_t len)
{
    const unsigned char* c1 = (unsigned char*)s1;
    const unsigned char* c2 = (unsigned char*)s2;

    // compare 8 bytes at a time
    while (len > 8) {
        if (*(uint64_t*)c1 != *(uint64_t*)c2) {
            return *(uint64_t*)c1 < *(uint64_t*)c2;
        }
        c1 += 8;
        c2 += 8;
        len -= 8;
    }
    switch (len) {
    case 1:
        if (*c1 != *c2) {
            return *c1 < *c2;
        }
        return 0;
    case 2:
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return *(uint16_t*)c1 < *(uint16_t*)c2;
        }
        return 0;
    case 3:
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return *(uint16_t*)c1 < *(uint16_t*)c2;
        }
        c1 += 2;
        c2 += 2;
        if (*c1 != *c2) {
            return *c1 < *c2;
        }
        return 0;
    case 4:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return *(uint32_t*)c1 < *(uint32_t*)c2;
        }
        return 0;
    case 5:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return *(uint32_t*)c1 < *(uint32_t*)c2;
        }
        c1 += 4;
        c2 += 4;
        if (*c1 != *c2) {
            return *c1 < *c2;
        }
        return 0;
    case 6:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return *(uint32_t*)c1 < *(uint32_t*)c2;
        }
        c1 += 4;
        c2 += 4;
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return *(uint16_t*)c1 < *(uint16_t*)c2;
        }
        return 0;
    case 7:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return *(uint32_t*)c1 < *(uint32_t*)c2;
        }
        c1 += 4;
        c2 += 4;
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return *(uint16_t*)c1 < *(uint16_t*)c2;
        }
        c1 += 2;
        c2 += 2;
        if (*c1 != *c2) {
            return *c1 < *c2;
        }
        return 0;
    case 8:
        if (*(uint64_t*)c1 != *(uint64_t*)c2) {
            return *(uint64_t*)c1 < *(uint64_t*)c2;
        }
        return 0;
    default:
        return 0;
    }
    return 0;
}


// Returns 0 if equal, else 1
FORCE_INLINE static int
BINARY_LT(const char* s1, const char* s2, size_t len)
{
    const unsigned char* c1 = (unsigned char*)s1;
    const unsigned char* c2 = (unsigned char*)s2;

    while (len > 8) {
        if (*(uint64_t*)c1 != *(uint64_t*)c2) {
            return 1;
        }
        c1 += 8;
        c2 += 8;
        len -= 8;
    }
    switch (len) {
    case 1:
        if (*c1 != *c2) {
            return 1;
        }
        return 0;
    case 2:
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return 1;
        }
        return 0;
    case 3:
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return 1;
        }
        c1 += 2;
        c2 += 2;
        if (*c1 != *c2) {
            return 1;
        }
        return 0;
    case 4:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return 1;
        }
        return 0;
    case 5:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return 1;
        }
        c1 += 4;
        c2 += 4;
        if (*c1 != *c2) {
            return 1;
        }
        return 0;
    case 6:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return 1;
        }
        c1 += 4;
        c2 += 4;
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return 1;
        }
        return 0;
    case 7:
        if (*(uint32_t*)c1 != *(uint32_t*)c2) {
            return 1;
        }
        c1 += 4;
        c2 += 4;
        if (*(uint16_t*)c1 != *(uint16_t*)c2) {
            return 1;
        }
        c1 += 2;
        c2 += 2;
        if (*c1 != *c2) {
            return 1;
        }
        return 0;
    case 8:
        if (*(uint64_t*)c1 != *(uint64_t*)c2) {
            return 1;
        }
        return 0;
    default:
        return 0;
    }
    return 0;
}



//-----------------------------------------------------------------------------------------------
// inplace heapsort
template <typename T>
static int
heapsort_(void* pVoidStart, int64_t n)
{
    T* start = (T*)pVoidStart;
    T     tmp, * a;
    int64_t i, j, l;

    /* The array needs to be offset by one for heapsort indexing */
    a = (T*)start - 1;

    for (l = n >> 1; l > 0; --l) {
        tmp = a[l];
        for (i = l, j = l << 1; j <= n;) {
            if (j < n&& COMPARE_LT(a[j], a[j + 1])) {
                j += 1;
            }
            if (COMPARE_LT(tmp, a[j])) {
                a[i] = a[j];
                i = j;
                j += j;
            }
            else {
                break;
            }
        }
        a[i] = tmp;
    }

    for (; n > 1;) {
        tmp = a[n];
        a[n] = a[1];
        n -= 1;
        for (i = 1, j = 2; j <= n;) {
            if (j < n && COMPARE_LT(a[j], a[j + 1])) {
                j++;
            }
            if (COMPARE_LT(tmp, a[j])) {
                a[i] = a[j];
                i = j;
                j += j;
            }
            else {
                break;
            }
        }
        a[i] = tmp;
    }

    return 0;
}



//-----------------------------------------------------------------------------------------------
// indirect heapsort
template <typename T, typename UINDEX>
static int
aheapsort_(void* vv1, void* tosort1, int64_t n)
{
    T* vv = (T*)vv1;
    UINDEX* tosort = (UINDEX*)tosort1;

    T* v = vv;
    UINDEX* a, tmp;
    int64_t i, j, l;
    /* The arrays need to be offset by one for heapsort indexing */
    a = tosort - 1;

    for (l = n >> 1; l > 0; --l) {
        tmp = a[l];
        for (i = l, j = l << 1; j <= n;) {
            if (j < n&& COMPARE_LT(v[a[j]], v[a[j + 1]])) {
                j += 1;
            }
            if (COMPARE_LT(v[tmp], v[a[j]])) {
                a[i] = a[j];
                i = j;
                j += j;
            }
            else {
                break;
            }
        }
        a[i] = tmp;
    }

    for (; n > 1;) {
        tmp = a[n];
        a[n] = a[1];
        n -= 1;
        for (i = 1, j = 2; j <= n;) {
            if (j < n && COMPARE_LT(v[a[j]], v[a[j + 1]])) {
                j++;
            }
            if (COMPARE_LT(v[tmp], v[a[j]])) {
                a[i] = a[j];
                i = j;
                j += j;
            }
            else {
                break;
            }
        }
        a[i] = tmp;
    }

    return 0;
}



//---------------------------
// For intergers and floats
template <typename T>
static int
quicksort_(void* pVoidStart, int64_t length)
{
    T* start = (T*)pVoidStart;
    T vp;
    T* pl = start;
    T* pr = pl + length - 1;
    T* stack[PYA_QS_STACK];
    T** sptr = stack;
    T* pm, * pi, * pj, * pk;

    int depth[PYA_QS_STACK];
    int* psdepth = depth;
    int cdepth = npy_get_msb(length) * 2;

    for (;;) {
        if (cdepth >= 0) {
            while ((pr - pl) > SMALL_QUICKSORT) {
                /* quicksort partition */
                pm = pl + ((pr - pl) >> 1);
                if (COMPARE_LT(*pm, *pl)) T_SWAP(*pm, *pl);
                if (COMPARE_LT(*pr, *pm)) T_SWAP(*pr, *pm);
                if (COMPARE_LT(*pm, *pl)) T_SWAP(*pm, *pl);
                vp = *pm;
                pi = pl;
                pj = pr - 1;
                T_SWAP(*pm, *pj);
                for (;;) {
                    do ++pi; while (COMPARE_LT(*pi, vp));
                    do --pj; while (COMPARE_LT(vp, *pj));
                    if (pi >= pj) {
                        break;
                    }
                    T_SWAP(*pi, *pj);
                }
                pk = pr - 1;
                T_SWAP(*pi, *pk);
                /* push largest partition on stack */
                if (pi - pl < pr - pi) {
                    *sptr++ = pi + 1;
                    *sptr++ = pr;
                    pr = pi - 1;
                }
                else {
                    *sptr++ = pl;
                    *sptr++ = pi - 1;
                    pl = pi + 1;
                }
                *psdepth++ = --cdepth;
            }

            /* insertion sort */
            for (pi = pl + 1; pi <= pr; ++pi) {
                vp = *pi;
                pj = pi;
                pk = pi - 1;
                while (pj > pl&& COMPARE_LT(vp, *pk)) {
                    *pj-- = *pk--;
                }
                *pj = vp;
            }
            if (sptr == stack) {
                break;
            }
            pr = *(--sptr);
            pl = *(--sptr);
            cdepth = *(--psdepth);
            continue;
        }
        else {
            heapsort_<T>(pl, pr - pl + 1);
            if (sptr == stack) {
                break;
            }
            pr = *(--sptr);
            pl = *(--sptr);
            cdepth = *(--psdepth);
        }
    }

    return 0;
}


//-----------------------------------------------------------------------------------------------
// argsort (indirect quicksort)
template <typename T, typename UINDEX>
static int
aquicksort_(void* vv1, void* tosort1, int64_t num)
{
    T* vv = (T*)vv1;
    UINDEX* tosort = (UINDEX *) tosort1;
    T* v = vv;
    T vp;
    UINDEX* pl = tosort;
    UINDEX* pr = tosort + num - 1;
    UINDEX* stack[PYA_QS_STACK];
    UINDEX** sptr = stack;
    UINDEX* pm, * pi, * pj, * pk, vi;
    int depth[PYA_QS_STACK];
    int* psdepth = depth;
    int cdepth = npy_get_msb(num) * 2;

    for (;;) {
        if (cdepth >= 0) {

            while ((pr - pl) > SMALL_QUICKSORT) {
                /* quicksort partition */
                pm = pl + ((pr - pl) >> 1);
                if (COMPARE_LT(v[*pm], v[*pl])) INTP_SWAP(*pm, *pl);
                if (COMPARE_LT(v[*pr], v[*pm])) INTP_SWAP(*pr, *pm);
                if (COMPARE_LT(v[*pm], v[*pl])) INTP_SWAP(*pm, *pl);
                vp = v[*pm];
                pi = pl;
                pj = pr - 1;
                INTP_SWAP(*pm, *pj);
                for (;;) {
                    do ++pi; while (COMPARE_LT(v[*pi], vp));
                    do --pj; while (COMPARE_LT(vp, v[*pj]));
                    if (pi >= pj) {
                        break;
                    }
                    INTP_SWAP(*pi, *pj);
                }
                pk = pr - 1;
                INTP_SWAP(*pi, *pk);
                /* push largest partition on stack */
                if (pi - pl < pr - pi) {
                    *sptr++ = pi + 1;
                    *sptr++ = pr;
                    pr = pi - 1;
                }
                else {
                    *sptr++ = pl;
                    *sptr++ = pi - 1;
                    pl = pi + 1;
                }
                *psdepth++ = --cdepth;
            }

            /* insertion sort */
            for (pi = pl + 1; pi <= pr; ++pi) {
                vi = *pi;
                vp = v[vi];
                pj = pi;
                pk = pi - 1;
                while (pj > pl&& COMPARE_LT(vp, v[*pk])) {
                    *pj-- = *pk--;
                }
                *pj = vi;
            }
        }
        else {
            aheapsort_<T, UINDEX>(vv, pl, (UINDEX)(pr - pl + 1));
        }

        if (sptr == stack) {
            break;
        }
        pr = *(--sptr);
        pl = *(--sptr);
        cdepth = *(--psdepth);
    }

    return 0;
}


//--------------------------------------------------------------------------------------
// Forward declaration
template <typename T>
static void
mergesort0_(T* pl, T* pr, T* pw);

//--------------------------------------------------------------------------------------
// Will return 1 if copied into workspace
// Will return 0 if NOT copied data into workspace, thus avoiding MEMCPY
template <typename T>
static int
mergesort0left_(T* pl, T* pr, T* pw)
{
    if (pr - pl > SMALL_MERGESORT) {
        /* merge sort */
        T* pm = pl + ((pr - pl) >> 1);

        // Solve right first
        mergesort0_(pm, pr, pw);

        // Now left
        mergesort0_(pl, pm, pw);

        if (COMPARE_LT(*pm, *(pm - 1))) {
            // For floats, we will work backwards from the right side
            // of the merge to search for nans
            // NOTE: integers do not need to find nans
            T* origpr = pr;

            // Merge into workspace...
            pr = FIND_NANS(pr, pm);

            T* pDest = pw;
            pw = pl;
            T* pwEnd = pm;

            while (pw < pwEnd && pm < pr) {
                const T cmpR = *pm;
                const T cmpL = *pw;

                // nans ok here because we moved pr pointer past all nans
                // only cmpL can have nans now
                if (cmpL <= cmpR) {
                    *pDest++ = cmpL; pw++;
                    continue;
                }
                else {
                    *pDest++ = cmpR; pm++;
                }

            }
            while (pw < pwEnd) {
                *pDest++ = *pw++;
            }

            // we are moving all of it into workspace
            // for floats, this picks up any nans on the far right
            while (pm < origpr) {
                *pDest++ = *pm++;
            }
            // data in workspace
            return 1;
        }
        return 0;
    }
    else {
        // NOTE 50% of sort time is spent here
        // Consider a vectorized bitonic sort
        // For floats, consider moving nans to the end as the first step
        // to avoid the more complicated nan comparison
        /* insertion sort */
        for (T* pi = pl + 1; pi < pr; ++pi) {
            const T vp = *pi;
            T* pj = pi;
            T* pk = pi - 1;
            while (pj > pl&& COMPARE_LT(vp, *pk)) {
                *pj-- = *pk--;
            }
            *pj = vp;
        }
    }
    return 0;
}



//--------------------------------------------------------------------------------------
template <typename T>
static void
mergesort0_(T* pl, T* pr, T* pw)
{
    if (pr - pl > SMALL_MERGESORT) {
        /* merge sort */
        T* pm =pl + ((pr - pl) >> 1);

        // Solve right first
        mergesort0_(pm, pr, pw);

        // Now the left hand side can use the full workspace
        int copiedIntoWorkSpace = mergesort0left_(pl, pm, pw);

        if (copiedIntoWorkSpace) {
            // is this check ok?
            // For floats, we will work backwards from the right side
            // of the merge to search for nans
            // NOTE: integers do not need to find nans

            // the workspace holds the left now
            T* pwEnd = pw + (pm - pl);

            // compare first value on right side (pm)
            // to last value on left (which is in ws now)
            if (COMPARE_LT(*pm, *(pwEnd - 1))) {

                // skip past nans at back of the workspace
                pr = FIND_NANS(pr, pm);

                // can skip copy because data in workspace
                //MEMCPYR(pw, pl, (pm - pl) * sizeof(T));

                // the destination changed, merge into left pointer
                T* pDest = pl;

                while (pw < pwEnd && pm < pr) {
                    const T cmpR = *pm;
                    const T cmpL = *pw;

                    // nans ok here because we moved pr pointer past all nans
                    // only cmpL can have nans now
                    if (cmpL <= cmpR) {
                        *pDest++ = cmpL; pw++;
                        continue;
                    }
                    else {
                        *pDest++ = cmpR; pm++;
                    }

                }
                while (pw < pwEnd) {
                    *pDest++ = *pw++;
                }
                // data not in workspace anymore
            }
            else {
                // Data is already sorted, but in wrong location
                // Copy from workspace to left
                MEMCPYR(pl, pw, (pm - pl) * sizeof(T));
            }
        }
        else if (COMPARE_LT(*pm, *(pm - 1))) {
            // For floats, we will work backwards from the right side
            // of the merge to search for nans
            // NOTE: integers do not need to find nans
            pr = FIND_NANS(pr, pm);
            MEMCPYR(pw, pl, (pm - pl) * sizeof(T));

            T* pwEnd = pw + (pm - pl);
            T* pDest = pl;

            while (pw < pwEnd && pm < pr) {
                const T cmpR = *pm;
                const T cmpL = *pw;

                // nans ok here because we moved pr pointer past all nans
                // only cmpL can have nans now
                if (cmpL <= cmpR) {
                    *pDest++ = cmpL; pw++;
                    continue;
                }
                else {
                    *pDest++ = cmpR; pm++;
                }

            }
            while (pw < pwEnd) {
                *pDest++ = *pw++;
            }                
        }

    }
    else {
        // NOTE 50% of sort time is spent here
        // Consider a vectorized bitonic sort
        // For floats, consider moving nans to the end as the first step
        // to avoid the more complicated nan comparison
        /* insertion sort */
        for (T* pi = pl + 1; pi < pr; ++pi) {
            const T vp = *pi;
            T* pj = pi;
            T* pk = pi - 1;
            while (pj > pl&& COMPARE_LT(vp, *pk)) {
                *pj-- = *pk--;
            }
            *pj = vp;
        }
    }
}


//--------------------------------------------------------------------------------------
// variable length merge sort
template <typename T>
static void
mergesort0string_(char* pl, char* pr, char* pw, int64_t strLen)
{
    char * pi, * pj, * pk, * pm;

    if (((pr - pl) / strLen) > SMALL_MERGESORT) {
        /* merge sort */
        pm = pl +  strLen * (((pr - pl)/strLen) >> 1);
        mergesort0string_<T>(pl, pm, pw, strLen);
        mergesort0string_<T>(pm, pr, pw, strLen);

        if (STRING_LT((T*)pm, (T*)(pm - strLen), strLen)) {
            // copy front (pl) to worksapce
            MEMCPYR(pw, pl, pm - pl);

            pi = pw + (pm - pl);
            pj = pw;
            pk = pl;
            while (pj < pi && pm < pr) {
                if (STRING_LT((T*)pm, (T*)pj, strLen)) {
                    STRING_COPY(pk, pm, strLen);
                    pk += strLen;
                    pm += strLen;
                }
                else {
                    STRING_COPY(pk, pj, strLen);
                    pk += strLen;
                    pj += strLen;
                }
            }
            while (pj < pi) {
                STRING_COPY(pk, pj, strLen);
                pk += strLen;
                pj += strLen;
            }
        }
    }
    else {

        /* insertion sort */
        for (pi = pl + strLen; pi < pr; pi += strLen) {
            // Copy into vp, a temp buffer
            STRING_COPY(pw, pi, strLen);
            pj = pi;
            pk = pi - strLen;
            while (pj > pl&& STRING_LT((T*)pw, (T*)pk, strLen)) {
                STRING_COPY(pj, pk, strLen);
                pj -= strLen;
                pk -= strLen;
            }
            STRING_COPY(pj, pw, strLen);
        }

    }
}

//-----------------------------------------------------------------------------------------------
template <typename T>
static int
mergesort_(void* start, int64_t length)
{
    T* pl, * pr, * pw;

    pl = (T*)start;
    pr = pl + length;

    // Consider alloc on stack
    const int64_t allocSize = (length / 2) * sizeof(T);
    pw = POSSIBLY_STACK_ALLOC_TYPE(T*, allocSize);
    if (pw == NULL) {
        return -1;
    }
    mergesort0_(pl, pr, pw);

    POSSIBLY_STACK_FREE(allocSize, pw);
    return 0;
}


