template <typename T>
static int
mergesortstring_(void* start, int64_t length, int64_t strLen)
{
    char* pl, * pr, * pw;

    pl = (char*)start;
    pr = pl + (length * strLen);

    // Consider alloc on stack
    const int64_t allocSize = (length / 2) * strLen;
    pw = (char*)WORKSPACE_ALLOC(allocSize);
    if (pw == NULL) {
        return -1;
    }
    mergesort0string_<T>(pl, pr, pw, strLen);

    WORKSPACE_FREE(pw);
    return 0;
}


//-----------------------------------------------------------------------------------------------
template <typename DATATYPE, typename UINDEX>
static void
amergesort0_string(UINDEX* pl, UINDEX* pr, const char* strItem, UINDEX* pw, int64_t strLen)
{
    const char* vp;
    UINDEX vi, * pi, * pj, * pk, * pm;

    if (pr - pl > SMALL_MERGESORT) {
        /* merge sort */
        pm = pl + ((pr - pl) >> 1);
        //printf("merge sort %p %p %p diff:%lld\n", pl, pm, pr, pr-pl);
        amergesort0_string<DATATYPE>(pl, pm, strItem, pw, strLen);
        amergesort0_string<DATATYPE>(pm, pr, strItem, pw, strLen);
        pm = pl + ((pr - pl) >> 1);

        if (STRING_LT((DATATYPE)(strItem + (*pm) * strLen), (DATATYPE)(strItem + (*(pm - 1)) * strLen), strLen)) {

            MEMCPYR(pw, pl, (pm - pl) * sizeof(UINDEX));

            pi = pw + (pm - pl);
            pj = pw;
            pk = pl;
            while (pj < pi && pm < pr) {
                if (STRING_LT((DATATYPE)(strItem + (*pm) * strLen), (DATATYPE)(strItem + (*pj) * strLen), strLen)) {
                    *pk++ = *pm++;
                }
                else {
                    *pk++ = *pj++;
                }
            }
            while (pj < pi) {
                *pk++ = *pj++;
            }
        }
    }
    else {
        /* insertion sort */
        for (pi = pl + 1; pi < pr; ++pi) {
            vi = *pi;
            vp = strItem + (vi * strLen);
            pj = pi;
            pk = pi - 1;
            while (pj > pl&& STRING_LT((DATATYPE)vp, (DATATYPE)(strItem + (*pk) * strLen), strLen)) {
                *pj-- = *pk--;
            }
            *pj = vi;
        }
    }
}


//-----------------------------------------------------------------------------------------------
// Forward declaration
template <typename T, typename UINDEX>
static void
amergesort0_(UINDEX* pl, UINDEX* pr, const T* v, UINDEX* pw);

//-----------------------------------------------------------------------------------------------
// T= data type == int16,int32,uint32,int64.uint64
// UINDEX = int32_t or int64_t
// returns 1 if copied into workspace
// returns 0 if not copied into workspace
template <typename T, typename UINDEX>
static int
amergesort0left_(UINDEX* pl, UINDEX* pr, const T* v, UINDEX* pw)
{
    if (pr - pl > SMALL_MERGESORT) {
        /* merge sort */
        UINDEX* pm = pl + ((pr - pl) >> 1);

        // merge right first since tail was merged last
        amergesort0_(pm, pr, v, pw);

        // merge left
        amergesort0_(pl, pm, v, pw);

        // check if already sorted
        // if the first element on the right is less than the last element on the left
        //printf("comparing %d to %d ", (int)pm[0], (int)pm[-1]);
        if (COMPARE_LT(v[*pm], v[*(pm - 1)])) {
            // Merge into workspace
            UINDEX* plEnd = pm;

            while (pl < plEnd && pm < pr) {

                if (COMPARE_LT(v[*pm], v[*pl])) {
                    *pw++ = *pm++;
                }
                else {
                    *pw++ = *pl++;
                }
            }
            while (pl < plEnd) {
                *pw++ = *pl++;
            }
            // we are moving all of it into workspace
            // for floats, this picks up any nans on the far right
            while (pm < pr) {
                 *pw++ = *pm++;
            }
            // data in workspace
            return 1;
        }
        return 0;
    }
    else {
        /* insertion sort */
        for (UINDEX* pi = pl + 1; pi < pr; ++pi) {
            UINDEX vi = *pi;
            const T vp = v[vi];
            UINDEX* pj = pi;
            UINDEX* pk = pi - 1;
            while (pj > pl && COMPARE_LT(vp, v[*pk])) {
                *pj-- = *pk--;
            }
            *pj = vi;
        }
    }
    return 0;
}


//-----------------------------------------------------------------------------------------------
// T= data type == int16,int32,uint32,int64.uint64
// UINDEX = int32_t or int64_t
template <typename T, typename UINDEX>
static void
amergesort0_(UINDEX* pl, UINDEX* pr, const T* v, UINDEX* pw)
{
    if (pr - pl > SMALL_MERGESORT) {
        /* merge sort */
        UINDEX* pm = pl + ((pr - pl) >> 1);

        // sort right first
        amergesort0_(pm, pr, v, pw);
        //amergesort0_(pl, pm, v, pw);

        // sort left next and check copied into workspace
        if (!amergesort0left_(pl, pm, v, pw)) {

            // was not copied into workspace
            if (!COMPARE_LT(v[*pm], v[*(pm - 1)])) {
                // nothing to do
                return;
            }
            // copy into workspace
            MEMCPYR(pw, pl, (pm - pl) * sizeof(UINDEX));
        }
        else {
            // NOTE: could have extra check here to see if workspace is already sorted
            // if so, just do a mempcpy from workspace to pl
        }

        //printf("merging %lld\n", pr - pl);
        // For floats, we will work backwards from the right side
        // of the merge to search for nans
        // NOTE: integers do not need to find nans

        // the workspace holds the left now
        UINDEX* pwEnd = pw + (pm - pl);

        // destination is left
        // moving from workspace into left

        while (pw < pwEnd && pm < pr) {
            if (v[*pm] < v[*pw]) {
                *pl++ = *pm++;
            }
            else {
                *pl++ = *pw++;
            }

        }
        while (pw < pwEnd) {
            *pl++ = *pw++;
        }

    }
    else {
        /* insertion sort */
        for (UINDEX* pi = pl + 1; pi < pr; ++pi) {
            UINDEX vi = *pi;
            const T vp = v[vi];
            UINDEX* pj = pi;
            UINDEX* pk = pi - 1;
            while (pj > pl && COMPARE_LT(vp, v[*pk])) {
                *pj-- = *pk--;
            }
            *pj = vi;
        }
    }
}

//-----------------------------------------------------------------------------------------------
// allocates workspace
template <typename T, typename UINDEX>
static int
amergesort_(void* v1, void* tosort1, int64_t length)
{
    T* v = (T*)v1;
    UINDEX* tosort = (UINDEX*)tosort1;

    UINDEX* pl, * pr, * pworkspace;

    pl = tosort;
    pr = pl + length;

    // ideally look for memory in the cache
    pworkspace = (UINDEX*)WORKSPACE_ALLOC((length / 2) * sizeof(UINDEX));
    if (pworkspace == NULL) {
        return -1;
    }
    amergesort0_<T, UINDEX>(pl, pr, v, pworkspace);
    WORKSPACE_FREE(pworkspace);

    return 0;
}

//-----------------------------------------------------------------------------------------------
// does not allocate workspace
template <typename T, typename UINDEX>
static void
amergesortworkspace_(void* v1, void* tosort1, int64_t length, int64_t notused, void* pworkspace)
{
    T* v = (T*)v1;
    UINDEX* tosort = (UINDEX*)tosort1;
    UINDEX* pl, * pr;

    pl = tosort;
    pr = pl + length;

    amergesort0_<T, UINDEX>(pl, pr, v, (UINDEX*)pworkspace);
}


