  operator T&() {
    if (!gotHam) std::rethrow_exception(spam);
    return ham;
  }

  T& get() {
    if (!gotHam) std::rethrow_exception(spam);
    return ham;
  }

  const T& get() const {
    if (!gotHam) std::rethrow_exception(spam);
    return ham;
  }

  template <class E>
  bool hasException() const {
    try {
      if (!gotHam) std::rethrow_exception(spam);
    } catch (const E& object) {
      return true;
    } catch (...) {
    }
    return false;
  }

  template <class F>
  static Expected fromCode(F fun) {
    try {
      return Expected(fun());
    } catch (...) {
      return fromException();
    }
  }
};

