#include <casacore/fits/FITS/FITSKeywordUtil.h>
#include <casacore/fits/FITS/FITSReader.h>
#include <casacore/fits/FITS/fits.h>
#include <casacore/measures/Measures/MDirection.h>
#include <fitsio.h>
#include <fstream>
#include <longnam.h>
