	struct Quat
	{
		Quat(void) { }
		Quat(float _x, float _y, float _z, float _w) : x(_x), y(_y), z(_z), w(_w) { }
		Quat Copy(void) const { return *this; }
		template <typename X> X Cast(void) const { return X(x, y, z, w); }

