template<>
inline auto
    kawe::ComponentInspector::drawComponentTweaker(entt::registry &world, entt::entity e, const CameraData &camera) const
    -> void
{
    static constexpr auto epsilon = 0.0001f;

    // todo : improve me
    {
        bool viewport_updated = false;

        Rect4<float> temp = {
            .x = camera.viewport.x,
            .y = 1.0f - camera.viewport.y,
            .w = camera.viewport.w,
