void Conversion_char_int(char a[9][9], int p[9][9])                  //转换函数，讲字符型数组  转化成整形数组，'.'变为0。  
{
	for (int i = 0; i < 9; i++)
		for (int j = 0; j < 9; j++)
		{
			if (a[i][j] == '.')
			{
				p[i][j] = 0;
			}
			else if (57 >= int(a[i][j]) && int(a[i][j]) >= 49)
			{
				p[i][j] = (a[i][j] - '0');
			}
			else
			{
				cout << "该数独题目不符合要求，请检查后重新输入。" << endl;
				system("pause");
			}
