  out += String(tempBuff)+"</p>";
  out += "<p>"+temp+"</p>";
  temp = "Current:"+String(current_mA,2)+"mA";
  out += "<p>"+temp+"</p>";
  temp = "Voltage:"+String(busvoltage,2)+"V";
  out += "<p>"+temp+"</p>";
  out+="<img src=\"/test.svg\" />";
