void fix(string &buf) {
  string res;
  int eol=0;

  if (buf[ buf.size()-1 ] == 10) { buf = buf.substr(0,buf.size()-1); eol=1; }

  unsigned int kde=0;
  while (1) {
    if (kde >= buf.size()) break;
    if (res.size() >= 40) break;
    int idx = buf[kde++];
    if (idx < 0) idx += 256;
    res += _replace[idx];
  }
  if (kde < buf.size()) res+="...";
  if (!eol) res += " (missing end-of-line character)";
  buf = res;
}

ifstream &mygetline(ifstream &sin, string &res) {
