  if (errors>10) printf("(skipping the next %d errors)\n",errors-10);

  if ((!f1) && (f2)) printf("%s terminated, %s continues:\n",l1,l2);
  if ((f1) && (!f2)) printf("%s terminated, %s continues:\n",l2,l1);
  int nrows=0;

  if (!buf1.empty()) { fix(buf1); printf("%8s %04d: %s\n",l1,++row,buf1.c_str()); }
  if (!buf2.empty()) { fix(buf2); printf("%8s %04d: %s\n",l2,++row,buf2.c_str()); }

  while (f1) { 
    row++; mygetline(f1,buf1); 
    if (buf1=="") break;
    nrows++;
    if (nrows <= 10) {
      fix(buf1);
