static void HandleKeyPresses(void)
{
	char k;
	int x,y;

	byte s = LastScanCode();
	k=editmgl->LastKeyPressed();
	if(k)
		lastKey=k;

	switch(s)
	{
		case SDL_SCANCODE_LEFT:
		case SDL_SCANCODE_KP_4:
			GetCamera(&x,&y);
			x-=TILE_WIDTH;
			if(x<0)
				x=0;
			PutCamera(x<<FIXSHIFT,y<<FIXSHIFT);
			break;
		case SDL_SCANCODE_UP:
		case SDL_SCANCODE_KP_8:
			GetCamera(&x,&y);
			y-=TILE_HEIGHT;
			if(y<0)
				y=0;
			PutCamera(x<<FIXSHIFT,y<<FIXSHIFT);
			break;
		case SDL_SCANCODE_RIGHT:
		case SDL_SCANCODE_KP_6:
			GetCamera(&x,&y);
			x+=TILE_WIDTH;
			if(x>curMap->width*TILE_WIDTH)
				x=curMap->width*TILE_WIDTH;
			PutCamera(x<<FIXSHIFT,y<<FIXSHIFT);
			break;
		case SDL_SCANCODE_DOWN:
		case SDL_SCANCODE_KP_2:
			GetCamera(&x,&y);
			y+=TILE_HEIGHT;
			if(y>curMap->height*TILE_HEIGHT)
				y=curMap->height*TILE_HEIGHT;
			PutCamera(x<<FIXSHIFT,y<<FIXSHIFT);
			break;
	}

	if(editMode==EDITMODE_EDIT)
	{
		switch(k)
		{
			case 'c':
				Cavernize(curMap);
				break;
			case 'f':
				editMode=EDITMODE_FILE;
				InitFileDialog();
				break;
			case 'w':
				editMode=EDITMODE_MAPMENU;
				InitMapDialog(&world,curMapNum);
				break;
			case ' ':
				editopt.plopMode++;
				if(editopt.plopMode>=MAXPLOP)
					editopt.plopMode=0;
				break;
			case 'b':
				editopt.brushSize++;
				if(editopt.brushSize>10)
					editopt.brushSize=1;
				break;
			case '-':
				editopt.curFloor--;
				if(editopt.curFloor>199)
					editopt.curFloor=199;
				break;
			case '=':
			case '+':
				editopt.curFloor++;
				if(editopt.curFloor>199)
					editopt.curFloor=0;
				break;
			case 'o':
				editopt.curWallFloor--;
				if(editopt.curWallFloor>199)
					editopt.curWallFloor=199;
				break;
			case 'p':
				editopt.curWallFloor++;
				if(editopt.curWallFloor>199)
					editopt.curWallFloor=0;
				break;
			case '[':
				editopt.curWall--;
				if(editopt.curWall>199)
					editopt.curWall=199;
				break;
			case ']':
				editopt.curWall++;
				if(editopt.curWall>199)
					editopt.curWall=0;
				break;
			case ',':
				editopt.curItem--;
				if(editopt.curItem>=MAX_ITMS)
					editopt.curItem=MAX_ITMS-1;
				break;
			case '.':
				editopt.curItem++;
				if(editopt.curItem>=MAX_ITMS)
					editopt.curItem=1;
				break;
			case ';':
				editopt.curBadguy--;
				if(editopt.curBadguy<1)
					editopt.curBadguy=NUM_MONSTERS-1;
				break;
			case '\'':
				editopt.curBadguy++;
				if(editopt.curBadguy>=NUM_MONSTERS)
					editopt.curBadguy=1;
				break;
			case 'A':
				curMap->Resize(curMap->width-1,curMap->height);
				break;
			case 'D':
				curMap->Resize(curMap->width+1,curMap->height);
				break;
			case 'W':
				curMap->Resize(curMap->width,curMap->height-1);
				break;
			case 'X':
				curMap->Resize(curMap->width,curMap->height+1);
				break;
			case '1':
				editopt.plopMode=0;
				break;
			case '2':
				editopt.plopMode=1;
				break;
			case '3':
				editopt.plopMode=2;
				break;
			case '4':
				editopt.plopMode=3;
				break;
			case '5':
				editopt.plopMode=4;
				break;
			case '6':
				editopt.plopMode=5;
				break;
			case '7':
				editopt.plopMode=6;
				break;
			case '8':
				editopt.plopMode=7;
				break;
			case '9':
				editopt.plopMode=8;
				break;
			case 8:
				Delete(tileX,tileY);
				break;
		}
	}
	else if(editMode==EDITMODE_FILE)
	{
		if(k)
		{
			if(!FileDialogKey(lastKey))
			{
				editMode=EDITMODE_EDIT;
				ExitFileDialog();
			}
			lastKey=0;
		}
	}
	else if(editMode==EDITMODE_TILELOAD)
	{
		if(k)
		{
			if(!TileDialogKey(lastKey))
			{
				editMode=EDITMODE_EDIT;
				ExitTileDialog();
			}
			lastKey=0;
		}
	}
	else if(editMode==EDITMODE_SPECIAL)
	{
		if(k)
		{
			if(!SpclDialogKey(lastKey))
			{
				editMode=EDITMODE_EDIT;
				ExitSpclDialog();
			}
			lastKey=0;
		}
	}
	else if(editMode==EDITMODE_MAPMENU)
	{
		if(k)
		{
			if(!MapDialogKey(lastKey))
			{
				editMode=EDITMODE_EDIT;
				ExitMapDialog();
			}
			lastKey=0;
		}
	}
	else
	{
		switch(k)
		{
			case 27:
				editMode=EDITMODE_EDIT;
				lastKey=0;
				break;
		}
	}
}

TASK(byte) LunaticEditor(MGLDraw *mgl)
{
	int lastTime=1;
	byte exitcode=0;

	editmgl=mgl;

	if(!InitEditor())
		CO_RETURN QUITGAME;

	exitcode=CONTINUE;
	while(exitcode==CONTINUE)
	{
		lastTime+=TimeLength();
		StartClock();
		HandleKeyPresses();
		exitcode=EditorRun(&lastTime);
		if(numRunsToMakeUp>0)
		{
			EditorDraw();
			AWAIT editmgl->Flip();
		}
		if(lastKey==27)
			exitcode=QUITGAME;

		if(!editmgl->Process())
			exitcode=QUITGAME;
		EndClock();
	}

	ExitEditor();
	CO_RETURN exitcode;
}

