static unsigned int transform(void *context, const unsigned char *data,
                              size_t nblks) {
  SHA512_CONTEXT *ctx = (SHA512_CONTEXT *)context;
  unsigned int burn;

#ifdef USE_AVX2
  if (ctx->use_avx2)
    return _gcry_sha512_transform_amd64_avx2(data, &ctx->state, nblks) +
           4 * sizeof(void *) + ASM_EXTRA_STACK;
#endif

#ifdef USE_AVX
  if (ctx->use_avx)
    return _gcry_sha512_transform_amd64_avx(data, &ctx->state, nblks) +
           4 * sizeof(void *) + ASM_EXTRA_STACK;
#endif

#ifdef USE_SSSE3
  if (ctx->use_ssse3)
    return _gcry_sha512_transform_amd64_ssse3(data, &ctx->state, nblks) +
           4 * sizeof(void *) + ASM_EXTRA_STACK;
#endif

#ifdef USE_ARM_NEON_ASM
  if (ctx->use_neon) {
    _gcry_sha512_transform_armv7_neon(&ctx->state, data, k, nblks);

    /* _gcry_sha512_transform_armv7_neon does not store sensitive data
     * to stack.  */
    return /* no burn_stack */ 0;
  }
#endif

#ifdef USE_ARM_ASM
  burn = _gcry_sha512_transform_arm(&ctx->state, data, k, nblks);
#else
  do {
    burn = transform_blk(&ctx->state, data) + 3 * sizeof(void *);
    data += 128;
  } while (--nblks);

#ifdef ASM_EXTRA_STACK
  /* 'transform_blk' is typically inlined and XMM6-XMM15 are stored at
   *  the prologue of this function. Therefore need to add ASM_EXTRA_STACK to
   *  here too.
   */
  burn += ASM_EXTRA_STACK;
#endif
#endif

  return burn;
}

/* The routine final terminates the computation and
 * returns the digest.
 * The handle is prepared for a new cycle, but adding bytes to the
 * handle will the destroy the returned buffer.
 * Returns: 64 bytes representing the digest.  When used for sha384,
 * we take the leftmost 48 of those bytes.
 */

static void sha512_final(void *context) {
  SHA512_CONTEXT *hd = (SHA512_CONTEXT *)context;
  unsigned int stack_burn_depth;
  u64 t, th, msb, lsb;
  byte *p;

  _gcry_md_block_write(context, NULL, 0); /* flush */
  ;

  t = hd->bctx.nblocks;
  /* if (sizeof t == sizeof hd->bctx.nblocks) */
  th = hd->bctx.nblocks_high;
  /* else */
  /*   th = hd->bctx.nblocks >> 64; In case we ever use u128  */

  /* multiply by 128 to make a byte count */
  lsb = t << 7;
  msb = (th << 7) | (t >> 57);
  /* add the count */
  t = lsb;
  if ((lsb += hd->bctx.count) < t) msb++;
  /* multiply by 8 to make a bit count */
  t = lsb;
  lsb <<= 3;
  msb <<= 3;
  msb |= t >> 61;

  if (hd->bctx.count < 112) {              /* enough room */
    hd->bctx.buf[hd->bctx.count++] = 0x80; /* pad */
    while (hd->bctx.count < 112) hd->bctx.buf[hd->bctx.count++] = 0; /* pad */
  } else {                                 /* need one extra block */
    hd->bctx.buf[hd->bctx.count++] = 0x80; /* pad character */
    while (hd->bctx.count < 128) hd->bctx.buf[hd->bctx.count++] = 0;
    _gcry_md_block_write(context, NULL, 0); /* flush */
    ;
    memset(hd->bctx.buf, 0, 112); /* fill next block with zeroes */
  }
  /* append the 128 bit count */
  buf_put_be64(hd->bctx.buf + 112, msb);
  buf_put_be64(hd->bctx.buf + 120, lsb);
  stack_burn_depth = transform(hd, hd->bctx.buf, 1);
  _gcry_burn_stack(stack_burn_depth);

  p = hd->bctx.buf;
#define X(a)                         \
  do {                               \
    buf_put_be64(p, hd->state.h##a); \
    p += 8;                          \
  } while (0)
  X(0);
  X(1);
  X(2);
  X(3);
  X(4);
  X(5);
  /* Note that these last two chunks are included even for SHA384.
     We just ignore them. */
  X(6);
  X(7);
#undef X
}

static byte *sha512_read(void *context) {
  SHA512_CONTEXT *hd = (SHA512_CONTEXT *)context;
  return hd->bctx.buf;
}

/* Shortcut functions which puts the hash value of the supplied buffer
 * into outbuf which must have a size of 64 bytes.  */
void _gcry_sha512_hash_buffer(void *outbuf, const void *buffer, size_t length) {
  SHA512_CONTEXT hd;

  sha512_init(&hd, 0);
  _gcry_md_block_write(&hd, buffer, length);
  sha512_final(&hd);
  memcpy(outbuf, hd.bctx.buf, 64);
}

/* Variant of the above shortcut function using multiple buffers.  */
void _gcry_sha512_hash_buffers(void *outbuf, const gcry_buffer_t *iov,
                               int iovcnt) {
  SHA512_CONTEXT hd;

  sha512_init(&hd, 0);
  for (; iovcnt > 0; iov++, iovcnt--)
    _gcry_md_block_write(&hd, (const char *)iov[0].data + iov[0].off,
                         iov[0].len);
  sha512_final(&hd);
  memcpy(outbuf, hd.bctx.buf, 64);
}

