      48);
  if (errtxt) goto failed;

  if (extended) {
    what = "long string";
    errtxt = _gcry_hash_selftest_check_one(
        GCRY_MD_SHA384, 0,
        "abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmn"
