        "\xC7\xD3\x29\xEE\xB6\xDD\x26\x54\x5E\x96\xE5\x5B\x87\x4B\xE9\x09",
        64);
    if (errtxt) goto failed;

    what = "one million \"a\"";
    errtxt = _gcry_hash_selftest_check_one(
        GCRY_MD_SHA512, 1, NULL, 0,
        "\xE7\x18\x48\x3D\x0C\xE7\x69\x64\x4E\x2E\x42\xC7\xBC\x15\xB4\x63"
        "\x8E\x1F\x98\xB1\x3B\x20\x44\x28\x56\x32\xA8\x03\xAF\xA9\x73\xEB"
        "\xDE\x0F\xF2\x44\x87\x7E\xA6\x0A\x4C\xB0\x43\x2C\xE5\x77\xC3\x1B"
        "\xEB\x00\x9C\x5C\x2C\x49\xAA\x2E\x4E\xAD\xB2\x17\xAD\x8C\xC0\x9B",
        64);
    if (errtxt) goto failed;
  }

  return 0; /* Succeeded. */

failed:
  if (report) report("digest", GCRY_MD_SHA512, what, errtxt);
  return GPG_ERR_SELFTEST_FAILED;
}

/* Run a full self-test for ALGO and return 0 on success.  */
static gpg_error_t run_selftests(int algo, int extended,
                                 selftest_report_func_t report) {
  gpg_error_t ec;

  switch (algo) {
    case GCRY_MD_SHA384:
      ec = selftests_sha384(extended, report);
      break;
    case GCRY_MD_SHA512:
      ec = selftests_sha512(extended, report);
      break;
    default:
      ec = GPG_ERR_DIGEST_ALGO;
      break;
  }
  return ec;
}

