					break;
				case ELEMENT_NORMAL:
					item->data_type = ERTD_EMPTY;
					item->render_style.display = ERT_BLOCK;

					//item->data = &obj->textContent;
					break;
				default:
					item->data_type = ERTD_EMPTY;
					break;
			}

			for (elix_rendertree_item *  q: item->children) {


			}
		}

