    install_new_poke(); if (!map_lv1_ss()) { remove_new_poke(); return -1; }

	if(Lv2Syscall1(6, HV_BASE + 0x3b8) == 0x7f83e37860000000ULL)
	{
		Lv2Syscall2(7, HV_BASE + 0x3b8, 0x7f83e378f8010098ULL);
