void reverse(char *src) {
  int l = strlen(src);
  char work[l+1];
  char *dst = work,
       *end_ptr = &src[l-1];

  for (int i=0; i<l; i++) {
    *dst++ = *end_ptr--;
  }
  *dst++ = '\0';
  strcpy(src, work);
}

