using namespace std;
int MAX = 100000;

struct UFDS {
	vector<int> p;
	int numSets;
	UFDS(int n) : p(n, 0), numSets(n) {
		for (int i = 0; i < n; ++i) p[i] = i;
	}
	int find(int x) {
		return (p[x] == x) ? x : p[x] = find(p[x]);
	}
	void merge(int x, int y) {
		int i = find(x), j = find(y);
		if (i == j) return;
		p[i] = j;
		--numSets;
	}
};

bool resolverCaso() {
	int a, b;
	cin >> a;
	if (!cin) return false;
	int c = 0;
	UFDS uf(MAX);
	while (a != -1) {
		cin >> b;
		if (uf.find(a) != uf.find(b)) 
			uf.merge(a, b);
		else c++;
		cin >> a;
	}
	cout << c << '\n';
	cin.ignore();
	return true;
}

