#include <iostream>
#include <chrono>
#include <vector>

#include <condition_variable>
#include <thread>

#include "htm4pwr.h"
#include "ThreadPool.h"

const uint64_t repeats = 1 << 2;

static void busy_wait(const int slowdown_repeats = 1 << 10)
{
	for (volatile int i = 0; i < slowdown_repeats; i++);
}

using Lock = htm4pwr::MutexLock;

template<typename T>
void slow_inc(T *data)
{
	{
		Lock lock;
		*data *= 2;
		*data += 2;
		*data /= 2;
	}
}

template<typename T>
void slow_dec(T *data)
{
	{
		Lock lock;
		*data *= 2;
		*data -= 2;
		*data /= 2;
	}
}

#ifndef ENABLE_TIMER
#define ENABLE_TIMER 1
#endif

int main()
{
	volatile uint64_t test_d = 0;
	auto testFunction = [&]{
		busy_wait();
		slow_inc(&test_d);
		slow_inc(&test_d);

		busy_wait();
		slow_inc(&test_d);
		slow_inc(&test_d);

		busy_wait();
		slow_dec(&test_d);
		slow_dec(&test_d);
		slow_dec(&test_d);
	};

	ThreadPool pool(4, ThreadPool::RUNNING);
	for (uint64_t i = 0; i < repeats; i++)
		pool.enqueue(testFunction);


#if ENABLE_TIMER
