            Rtos::delayms(1);
        }

        c = read();
        buf.push_back(c);
        // debug("%c", c);

        if (strchr(token, c) != nullptr){
            buf.push_back('\0');
            return Text(& buf.front());
        }
    }
}

void EspStateBar::eventHandler(){
    while (true) {
        Text && resp = readUntil(':', '\n');
        if (resp.length() == 0){
