template < class Solution >
Solution generalProblemSolver(Solution s0,
		function < double (Solution) > fitness,
		function < bool (Solution) > termCondition,
		function < Solution (Solution) > getNeighbour
	) {
	int i = 0;
	std::list < Solution > s;
	s.push_back(s0);
	// warunek zakończenia
