  printVector("VectorA",vectorA);

  /* If the value is prime then is stored in vectorB */
  for (int i = 0; i < 10; i++){
  	if(isPrime(vectorA[i])){
  		vectorB[i] = vectorA[i];
	  }else{
		vectorB[i] = 0;
	}
  }
  /* Sum all numbers in vectorB */
  for(int i = 0; i < 10; i++){
  	result += vectorB[i];
