/* This function verifies is a given number is prime or not */
bool isPrime (const int prime) {
  int counter = 1;
  if (prime == 0){
      return false;
    }else {
      for (int i = 2; i < prime ; i++){
          	if ((prime % i ) == 0) {
	            counter++;
	         }
      }
	}
    if(counter > 1){
    	return false;
	}    
   return true;
}

