      p += 8;
      v2 = XXH64_round(v2, XXH_get64bits(p));
      p += 8;
      v3 = XXH64_round(v3, XXH_get64bits(p));
      p += 8;
      v4 = XXH64_round(v4, XXH_get64bits(p));
      p += 8;
