//
//  ФУНКЦИЯ: WndProc(HWND, UINT, WPARAM, LPARAM)
//
//  ЦЕЛЬ: Обрабатывает сообщения в главном окне.
//
//  WM_COMMAND  - обработать меню приложения
//  WM_PAINT    - Отрисовка главного окна
//  WM_DESTROY  - отправить сообщение о выходе и вернуться
//
//
LRESULT CALLBACK WndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_CREATE:
        {
            onCreate(hWnd);
        }
        break;
    case WM_COMMAND:
        {
            int wmId = LOWORD(wParam);
            // Разобрать выбор в меню:
            switch (wmId)
            {
            case IDM_LOGOUT:
                EnumChildWindows(hWnd, DestoryChildCallback, NULL);
                ptClient->~ChatClient();
                onCreate(hWnd);
                break;
            case IDM_ABOUT:
                CreateDialog(hInst, MAKEINTRESOURCE(IDD_ABOUTBOX), hWnd, About);
                //DialogBox(hInst, MAKEINTRESOURCE(IDD_ABOUTBOX), hWnd, About);
                break;
            case IDM_EXIT:
                DestroyWindow(hWnd);
                break;
            case ID_BUTTON_SEND:
            {
                int n = GetWindowText(hEditText, lpString, 100);
                if (n > 0) {
                    SetWindowText(hEditText, TEXT(""));
                    WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, lpString, -1, lpUtf, 100, NULL, NULL);
                    ptClient->sendMessage(lpUtf);
                }
                break;
            }
            case ID_CHECKBOX:
                checked = !checked;
                if (checked) {
                    CheckDlgButton(hWnd, ID_CHECKBOX, BST_CHECKED);
                }
                else {
                    CheckDlgButton(hWnd, ID_CHECKBOX, BST_UNCHECKED);
                }
                break;
            default:
                return DefWindowProc(hWnd, message, wParam, lParam);
            }
        }
        break;
    case WM_RBUTTONDOWN:
    {
        HMENU hMenu = CreatePopupMenu();
        AppendMenu(hMenu, MF_STRING, IDM_ABOUT, TEXT("About"));
        AppendMenu(hMenu, MF_STRING, ID_BUTTON_SEND, TEXT("Send message"));
        POINT p;
        p.x = LOWORD(lParam);
        p.y = HIWORD(lParam);
        ClientToScreen(hWnd, &p);
        TrackPopupMenu(hMenu, TPM_LEFTALIGN | TPM_TOPALIGN,
            p.x, p.y, 0, hWnd, NULL);
        break;
    }
    case WM_PAINT:
        {
            PAINTSTRUCT ps;
            HDC hdc = BeginPaint(hWnd, &ps);

            HDC hCompatibleDC;
            HANDLE hOldBitmap;
            BITMAP Bitmap;

            GetObject(hImg, sizeof(BITMAP), &Bitmap);
            hCompatibleDC = CreateCompatibleDC(hdc);
            hOldBitmap = SelectObject(hCompatibleDC, hImg);
            StretchBlt(hdc, 520, 100, 100, 100, hCompatibleDC, 0, 0, 100,
                100, SRCCOPY);
            SelectObject(hCompatibleDC, hOldBitmap);
            DeleteDC(hCompatibleDC);

            EndPaint(hWnd, &ps);
        }
        break;
    case WM_DESTROY:
        delete ptClient;
        delete lpUtf;
        delete username;
        delete lpString;
        DeleteObject(hImg);
        PostQuitMessage(0);
        break;
    default:
        return DefWindowProc(hWnd, message, wParam, lParam);
    }
    return 0;
}

// Обработчик сообщений для окна "О программе".
INT_PTR CALLBACK About(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam)
{
    UNREFERENCED_PARAMETER(lParam);
    switch (message)
    {
    case WM_INITDIALOG:
        return (INT_PTR)TRUE;

    case WM_COMMAND:
        if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
        {
            EndDialog(hDlg, LOWORD(wParam));
            return (INT_PTR)TRUE;
        }
        break;
    }
    return (INT_PTR)FALSE;
}

