  {
    socksIp = argv[1];
  }

  InetAddress socksAddr(
    socksIp,
    s_nSocksPort);

  DemuxServer server(
    &loop, 
    listenAddr, 
    socksAddr);

  server.start();
  loop.loop();
}*/

