#include "openmp_integral_image.h"

#define STB_IMAGE_IMPLEMENTATION
#include "stb_image.h"
#include <iostream>
#define STB_IMAGE_WRITE_IMPLEMENTATION
#include "stb_image_write.h"

#include "input_parser.h"

#include <omp.h>

void print_help(){
    std::cout << "usage: openmp -p <input image path> [-t <number of threads (int) (default:platform dependent)>] [-json]" << std::endl << std::endl;

    std::cout << "To see this menu again: openmp -h" << std::endl;
}

int main(int argc, char **argv){
    InputParser input(argc, argv);
    if(input.cmdOptionExists("-h")){
        print_help();
        return 0;
    }

    if(input.cmdOptionExists("-p")){
        std::string in_file = input.getCmdOption("-p");
        if (in_file == "")
        {
            std::cout << "No input file!\n\n";
            print_help();
            return 2;
        }

        bool json = input.cmdOptionExists("-json");

    	int width, height, bpp;
    	uint8_t* image = stbi_load(in_file.c_str(), &width, &height, &bpp, 1);
        unsigned long* long_image = new unsigned long[height*width];

        for (int i = 0; i < height*width; ++i)
        {
            long_image[i] = image[i];
        }
    	if(!json){
        std::cout << "w: " << width << " h: " << height << " b: " << bpp << std::endl;

        std::cout << "Calculating Integral Image..." << std::endl;
        }

        int threads = 0;

        if(input.cmdOptionExists("-t")){
            std::string num_threads_string = input.getCmdOption("-t");
            if (num_threads_string != ""){
                threads = atoi(num_threads_string.c_str());
            }
        }

        double start_omp = omp_get_wtime();

        unsigned long* integral_image = integralImageMP(long_image, height, width, threads);

        double end_omp = omp_get_wtime();

        double time_tot = end_omp - start_omp;

        if (!json)
        {
            std::cout << "Total time wall time omp: " << time_tot <<std::endl;
        }

        if (json)
        {
            std::cout << "{\"time\": " << time_tot << ", \"width\": " << width << ", \"height\": " << height << "}" << std::endl;
        }

        delete [] integral_image;
        delete [] long_image;

        stbi_image_free(image);

    	return 0;
    } else {
        std::cout << "No input file!\n\n";
        print_help();
        return 1;
    }
}

