        rbf_core.Print_TimerRecord_Single(outpath+pcname+"_time.txt");
    }








    return 0;
}







RBF_Paras Set_RBF_PARA(){

    RBF_Paras para;
    RBF_InitMethod initmethod = Lamnbda_Search;

