	int idx = 0;
	int next = 0;
	int nextTot = 0;
	int total = 0;

	bool first = true;

	ifstream input;

	input.open(fname);
	string temp = "";

	while(getline(input, temp))
	{
		next =  atoi(temp.c_str());
		if (first)
		{
