				first = false;
		}
		else
		{
			nextTot = 0;

			for (int i = 0; i < 3; i++)
				nextTot += last[i];


			if (nextTot > lastTot)
				total++;
			lastTot = nextTot;
		}
		last[idx] = next;

		idx = (idx + 1) % 3;



	}

	cout << total << '\n';
	return 0;
}

