size_t  splitString(const string& strSrc, const string& strDelims, vector<string>& strDest)
{
	string delims = strDelims;
	string STR;
	if (delims.empty()) delims = " **";
	string::size_type pos = 0;
	string::size_type LEN = strSrc.size();
	while (pos < LEN) {
		STR = "";
		while ((delims.find(strSrc[pos]) != std::string::npos) && (pos < LEN))
		{
			++pos;
		}
		if (pos == LEN) {
			return strDest.size();
		}
		while ((delims.find(strSrc[pos]) == std::string::npos) && (pos < LEN))
		{
			STR += strSrc[pos++];
		}
		if (!STR.empty())
		{
			strDest.push_back(STR);
		}
	}
	return strDest.size();
}
bool tryParseDouble(const char *s, const char *s_end, double *result)
{
	if (s >= s_end)
	{
		return false;
	}
	double mantissa = 0.0;
	int exponent = 0;
	char sign = '+';
	char exp_sign = '+';
	char const *curr = s;
	int read = 0;
	bool end_not_reached = false;
	if (*curr == '+' || *curr == '-')
	{
