	}
	else if (isdigit(*curr)) { /* Pass through. */ }
	else
	{
		goto fail;
	}
	while ((end_not_reached = (curr != s_end)) && isdigit(*curr))
	{
		mantissa *= 10;
		mantissa += static_cast<int>(*curr - 0x30);
		curr++;	read++;
	}
	if (read == 0)
		goto fail;
	if (!end_not_reached)
		goto assemble;
	if (*curr == '.')
	{
		curr++;
		read = 1;
		while ((end_not_reached = (curr != s_end)) && isdigit(*curr))
		{
			mantissa += static_cast<int>(*curr - 0x30) * pow(10.0, -read);
