#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <cstring>
#include "CL/opencl.h"
#include "AOCLUtils/aocl_utils.h"

using namespace aocl_utils;

#define STRING_BUFFER_LEN 1024

static size_t m = 200;
static size_t n = 400;
static size_t p = 600;

// OpenCL runtime configuration
static cl_platform_id platform = NULL;
static cl_device_id device = NULL;
static cl_context context = NULL;
static cl_command_queue queue = NULL;
static cl_kernel kernel = NULL;
static cl_program program = NULL;

// Control whether the emulator should be used.
static bool use_emulator = false;

// Function prototypes
bool init();
void cleanup();
static void device_info_ulong( cl_device_id device, cl_device_info param, const char* name);
static void device_info_uint( cl_device_id device, cl_device_info param, const char* name);
static void device_info_bool( cl_device_id device, cl_device_info param, const char* name);
static void device_info_string( cl_device_id device, cl_device_info param, const char* name);
static void display_device_info( cl_device_id device );

//using namespace aocl_utils;

int main(int argc, char** argv) {
  Options options(argc, argv);

  int ret;
  m = atoi(argv[1]);
  n = atoi(argv[2]);
  p = atoi(argv[3]);
  // Optional argument to specify whether the emulator should be used.
  if(options.has("emulator")) {
  use_emulator = options.get<bool>("emulator");
  }

  cl_int status;

  if (!init()) {
      return -1;
  }

  //initialize the matrices as arrays using calloc
  float* matrixA = (float *)calloc(m * n, sizeof(float));
  float* matrixB = (float *)calloc(n * p, sizeof(float));
  float* matrixC = (float *)calloc(m * p, sizeof(float));
  float* matrixD = (float *)calloc(m * p, sizeof(float));
  for (int i = 0; i < m * n; i++) {
      matrixA[i] = 1.0f;
  }
  for (int i = 0; i < n * p; i++) {
      matrixB[i] = 2.0f;
  }
  for (int i = 0; i < m * p; i++) {
      matrixC[i] = 3.0f;
  }



  // allocate space for Matrix A on the device 
  cl_mem bufferA = clCreateBuffer(context, CL_MEM_READ_ONLY,
  m * n * sizeof(float), NULL, &ret);
  // copy Matrix A to the device 
  clEnqueueWriteBuffer(queue, bufferA, CL_TRUE, 0,
  m * n * sizeof(float), (void *)matrixA, 0, NULL, NULL);

  // allocate space for Matrix B on the device 
  cl_mem bufferB = clCreateBuffer(context, CL_MEM_READ_ONLY,
  n * p * sizeof(float), NULL, &ret);
  // copy Matrix B to the device 
  clEnqueueWriteBuffer(queue, bufferB, CL_TRUE, 0,
  n * p * sizeof(float), (void *)matrixB, 0, NULL, NULL);

  // allocate space for Matrix C on the device 
  cl_mem bufferC = clCreateBuffer(context, CL_MEM_READ_ONLY,
  m * p * sizeof(float), NULL, &ret);
  // copy Matrix C to the device 
  clEnqueueWriteBuffer(queue, bufferC, CL_TRUE, 0,
  m * p * sizeof(float), (void *)matrixC, 0, NULL, NULL);

  // allocate space for Matrix D on the device 
  cl_mem bufferD = clCreateBuffer(context, CL_MEM_WRITE_ONLY,
  m * p * sizeof(float), NULL, &ret);
  // copy Matrix D to the device 
  clEnqueueWriteBuffer(queue, bufferD, CL_TRUE, 0,
  m * p * sizeof(float), (void *)matrixD, 0, NULL, NULL);



  // Set the kernel arguments 
  status = clSetKernelArg(kernel, 0, sizeof(cl_mem), (void *)&bufferD);
  status = clSetKernelArg(kernel, 1, sizeof(cl_int), (void *)&m);
  status = clSetKernelArg(kernel, 2, sizeof(cl_int), (void *)&n);
  status = clSetKernelArg(kernel, 3, sizeof(cl_int), (void *)&p);
  status = clSetKernelArg(kernel, 4, sizeof(cl_mem), (void *)&bufferA);
  status = clSetKernelArg(kernel, 5, sizeof(cl_mem), (void *)&bufferB);
  status = clSetKernelArg(kernel, 6, sizeof(cl_mem), (void *)&bufferC);
  checkError(status, "Failed to set kernel arg ");

  printf("\nKernel initialization is complete.\n");
  printf("Launching the kernel...\n\n");

  // Configure work set over which the kernel will execute
  size_t globalws[2]={m, p};
  size_t localws[2] = {2, 2};

  // Execute the kernel 
  status = clEnqueueNDRangeKernel(queue, kernel, 2, NULL,
      globalws, localws, 0, NULL, NULL);

  // it is important to check the return value.
  checkError(status, "Failed to launch kernel");

  // Wait for command queue to complete pending events
  status = clFinish(queue);
  checkError(status, "Failed to finish");

  printf("\nKernel execution is complete.\n");

  // Copy the output data back to the host 
  clEnqueueReadBuffer(queue, bufferD, CL_TRUE, 0, m * p * sizeof(float),
         (void *)matrixD, 0, NULL, NULL);

  //print results
  printf("Top row of matrix D: [");
  for (int i = 0; i < m; i++) {
      printf("%f", matrixD[i]);
      if (i != m - 1) {
          printf(", ");
      }
  }
  printf("]\n");
  // free resources allocated
  free (matrixA);
  free (matrixB);
  free (matrixC);
  free (matrixD);
  cleanup();

  return 0;
}

// Free the resources allocated during initialization
void cleanup() {
  if(kernel) {
    clReleaseKernel(kernel);  
  }
  if(program) {
    clReleaseProgram(program);
  }
  if(queue) {
    clReleaseCommandQueue(queue);
  }
  if(context) {
    clReleaseContext(context);
  }
}

bool init() {
  cl_int status;

  if(!setCwdToExeDir()) {
    return false;
  }

  // Get the OpenCL platform.
  if (use_emulator) {
    platform = findPlatform("Intel(R) FPGA Emulation Platform for OpenCL(TM)");
  } else {
    platform = findPlatform("Intel(R) FPGA SDK for OpenCL(TM)");
  }
  if(platform == NULL) {
    printf("ERROR: Unable to find Intel(R) FPGA OpenCL platform.\n");
    return false;
  }

  // User-visible output - Platform information
  {
    char char_buffer[STRING_BUFFER_LEN]; 
    printf("Querying platform for info:\n");
    printf("==========================\n");
    clGetPlatformInfo(platform, CL_PLATFORM_NAME, STRING_BUFFER_LEN, char_buffer, NULL);
    printf("%-40s = %s\n", "CL_PLATFORM_NAME", char_buffer);
    clGetPlatformInfo(platform, CL_PLATFORM_VENDOR, STRING_BUFFER_LEN, char_buffer, NULL);
    printf("%-40s = %s\n", "CL_PLATFORM_VENDOR ", char_buffer);
    clGetPlatformInfo(platform, CL_PLATFORM_VERSION, STRING_BUFFER_LEN, char_buffer, NULL);
    printf("%-40s = %s\n\n", "CL_PLATFORM_VERSION ", char_buffer);
  }

  // Query the available OpenCL devices.
  scoped_array<cl_device_id> devices;
  cl_uint num_devices;

  devices.reset(getDevices(platform, CL_DEVICE_TYPE_ALL, &num_devices));

  // We'll just use the first device.
  device = devices[0];

  // Display some device information.
  display_device_info(device);

  // Create the context.
  context = clCreateContext(NULL, 1, &device, &oclContextCallback, NULL, &status);
  checkError(status, "Failed to create context");

  // Create the command queue.
  queue = clCreateCommandQueue(context, device, CL_QUEUE_PROFILING_ENABLE, &status);
  checkError(status, "Failed to create command queue");

  // Create the program.
  std::string binary_file = getBoardBinaryFile("matrix_add_mult", device);
  printf("Using AOCX: %s\n", binary_file.c_str());
  program = createProgramFromBinary(context, binary_file.c_str(), &device, 1);

  // Build the program that was just created.
  status = clBuildProgram(program, 0, NULL, "", NULL, NULL);
  checkError(status, "Failed to build program");

  // Create the kernel - name passed in here must match kernel name in the
  // original CL file, that was compiled into an AOCX file using the AOC tool
  const char *kernel_name = "MultAdd";  // Kernel name, as defined in the CL file
  kernel = clCreateKernel(program, kernel_name, &status);
  checkError(status, "Failed to create kernel");

  return true;
}

