    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < 3; ++i) scanf("%s", s + i);
    int shift = (s[0][0] - s[1][0] + 26) % 26;
    for (int i = 0; i < m; ++i) s[2][i] = 'A' + (s[2][i] - 'A' + shift) % 26;
