    for(I i = 0; i < n; ++i) {
        if(t[i] != 0) {
            continue;
        }

        I current = 0;
        I b = i + 1;
        while(b < n) {
            if(t[b] == current + 1) {
                ++current;
                if(current == EIGHT - 1) {
