    int counter = 0;
    string Letter;
    vector<int> vect;
    vect = returnQuaternary(k, np);

    counter = vect.size()-1;
    while(counter >= 0)
    {
        Letter = Mapa[vect[counter]];
        s.append(Letter);
        counter--;       
    }

    counter = 0;
    while(counter < vect.size())
    {
        Letter = Mapa[vect[counter]];
        s.append(Letter);
        counter++;
    }

