/* retrieve information on this or possibly another file */
void input_vgmstream::getfileinfo(char *filename, char *title, int *length_in_ms, int *sample_rate, int *channels, abort_callback & p_abort) {

    VGMSTREAM * infostream;
    if (length_in_ms)
    {
        *length_in_ms=-1000;
