class Solution {
private:
    int n;
    vector<int> nums;
    vector<char> ops;
    vector<int> helper(int l, int r) {
        vector<int> result;
        if (l == r) return {nums[l]};
        for (int i = l; i < r; ++i) {
            auto left = helper(l, i);
            auto right = helper(i+1, r);
            for (int x: left) {
                for (int y: right) {
                    switch (ops[i])
                    {
                    case '+':
                        result.push_back(x+y);
                        break;
                    case '-':
                        result.push_back(x-y);
                        break;
                    case '*':
                        result.push_back(x*y);
                        break;
                    }
                }
            }
        }
        return result;
    }
public:
    vector<int> diffWaysToCompute(string input) {
        n = input.length();
        const char *input_cstr = input.c_str();
