char *
rstrdup(const char *str) {
	if (!str) return NULL;
	char* rstr = strdup(str);
    reverse_string(rstr);
    return rstr;
}

void
reverse_string(char *str) {
	if (!str) return;
	int len = strlen(str);
	char* start = str;
	char* end = str + len - 1;
	while(start < end) {
		char tmp = *start;
        *start = *end;
        *end = tmp;
		start++; end--;
	} 
   return;
}

