using namespace std;
typedef pair<int,int> scpair;
class Solution {
public:
	int n;
	vector <scpair> a;
	vector<int> twoSum(vector<int> &numbers, int target) {
		n=numbers.size();
		a.resize(n);
		for (int i=0;i<n;i++){
			a[i]=scpair(numbers[i],i+1);
		}
		sort(a.begin(),a.end());
		vector <int> res;
		for (int i=0;i<n-1;i++){
			int left=target-a[i].first;
			int p=lower_bound(a.begin()+i+1,a.end(),scpair(left,0))-a.begin();
