int get_min_express() {
    int i = 0, j = 1, k = 0;
    while (i < len and j < len and k < len) {
        if (s[i+k] > s[j+k]) {
            i += k + 1;
            k = 0;
        } else if (s[i+k] < s[j+k]) {
            j += k + 1;
            k = 0;
        } else {
            k++;
        }
        if (i == j)
            ++i;
    }
    return min(i, j);
}

