BOOL LoadKeyboard(LPSTR fileName, LPKEYBOARD *lpKeyboard)
{
	DWORD sz;
	LPBYTE buf;
	HANDLE hFile;
	LPKEYBOARD kbp;
  PBYTE filebase;

	if(!fileName || !lpKeyboard)
	{
		Err("Bad Filename");
		return FALSE;
	}

	hFile = CreateFile(fileName, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL);
	if(hFile == INVALID_HANDLE_VALUE)
	{
		Err("Could not open file");
		return FALSE;
	}

	sz = GetFileSize(hFile, NULL);

#ifdef _WIN64
	buf = new BYTE[sz*3];
#else
	buf = new BYTE[sz];
#endif

	if(!buf)
	{
		CloseHandle(hFile);
		Err("Not allocmem");
		return FALSE;
	}
#ifdef _WIN64
	filebase = buf + sz*2;
#else
	filebase = buf;
#endif

	ReadFile(hFile, filebase, sz, &sz, NULL);
	CloseHandle(hFile);

  PKEYMAN64THREADDATA _td = ThreadGlobals();
  if(!_td) return FALSE;

	if(*LPDWORD(filebase) != FILEID_COMPILED)
	{
		delete buf; 
    Err("Invalid file");
    return FALSE;
	}

	if(!VerifyKeyboard(filebase, sz)) return FALSE;

#ifdef _WIN64
	kbp = CopyKeyboard(buf, filebase, sz);
#else
	kbp = FixupKeyboard(buf, filebase, sz);
#endif

  if(!kbp) return FALSE;

	if(kbp->dwIdentifier != FILEID_COMPILED) { delete buf; Err("errNotFileID"); return FALSE; }

  kbp->hBitmap = LoadBitmapFileEx(filebase);

	*lpKeyboard = kbp;

	return TRUE;
}



