struct Edge
{
	int To, Next;
	double Pow;

	Edge(int to, double pow, int next) :
		To(to), Pow(pow), Next(next) { }

	Edge() { }
} E[1000001];

int G[1001], cnt, Cnt[1001];
double dis[1001];
bool inq[1001];

void AddEdge(int from, int to, double pow)
{
	E[++cnt] = Edge(to, pow, G[from]);
	G[from] = cnt;
