		cnt = 0;
		for (int i = 1; i <= n; i++)
			for (int j = 1; j <= m; j++)
			{
				int w;
				cin >> w;
				AddEdge(j + n, i, log(u) - log(w));
				AddEdge(i, j + n, log(w) - log(l));
			}
