            *len = size_;
            memcpy(data_ + sizeof(uint32_t), str.c_str(), size_);
        }

        ~Data_S(){
            if(data_ != nullptr)  delete []data_;
        }

        char *raw_data(){
            return data_;
        }

        uint32_t size(){
