using namespace std;
typedef long long ll;
const int MM = 1e5+1;

int N, L, ps[MM];
char v[MM];
int bit[MM<<1];
ll ans;

void update(int i){
    for(i += MM; i < (MM<<1); i += i&-i)
        bit[i]++;
}

int query(int i){
    int ret = 0;
    for(i += MM; i; i -= i&-i)
        ret += bit[i];
    return ret;
}

int main(){

    scan(N, L);

    for(int i = 0,a; i < N; i++){
        scan(a);
        v[i] = ((a >= L) ? 1 : -1);
        ps[i] = v[i] + ps[i-1];
    }

    update(0);

    for(int i = 0; i < N; i++){
        ans += query(ps[i]);
        update(ps[i]);
    }

    print(ans);

    return 0;
}

