  EXPECT_TRUE(eventInfo == nullptr);

  parentEventInfo = registrar.event(id1);
  EXPECT_TRUE(parentEventInfo->unregisterCallback(callbackId));

  EXPECT_TRUE(registrar.unregisterEvent(id1));
  parentEventInfo = registrar.event(id1);
  EXPECT_TRUE(parentEventInfo == nullptr);
