// Programmer: <NAME>.

#include "stdafx.h"
#include "levels.h"

int main();

// class to create player objects and easily set their attributes
class player {
public:
	player() {

	}

	float walkSpeed = 0.2;
	float runSpeed = 0.5;
	//float walkSpeed = 0.05;
	//float runSpeed = 0.1;
	int playerHealth = 5;
	int playerAttackDmg;
	bool playerAttacked = false;
