int itktubeMetaClassPDFTest( int argc, char * argv[] )
{
  if( argc != 2 )
    {
    std::cout << "Usage: testname <tempfilename>" << std::endl;
    return EXIT_FAILURE;
    }

  itk::tube::MetaClassPDF pdf1;

