void smallerleft(int array[], int n){

    stack<int> s;

    for(int i =0;i<n;i++){

        while(!s.empty() && s.top() >= array[i]){
            s.pop();
        }

        if(s.empty()) cout<<"-1"<<" ";
        else cout<<s.top()<<" ";


        s.push(array[i]);
