    btn0->func = doSomething;
    btn1->func = circlePath;

    cicl = new Circle(0,0,1,0,1,0);

    animating = false;
    circle = false;
    up = true;

    singleton = this;

    theta = 0;
    inc = 2*M_PI/60;

    r = 0.5;
    cx = 0;
    cy = 0;
}

void App::draw() const {

    text->draw();

    btn0->draw();
    btn1->draw();

    cicl->draw();

    pic->draw(0);
}

void App::leftMouseDown(float x, float y){
    //std::cout << "Mouse down at " << x << ", " << y << std::endl;
    // if (x >= 0.0 && x <= 0.3 && y <= 0 && y >= -0.1){
    //     std::cout << "Clicked button1" << std::endl;
    //     //animating = !animating;
    // }
    btn0->handle(x, y);
    btn1->handle(x, y);
}

void App::idle(){
    if (animating){
        if (pic->getX() >= 1 - 0.25){
            up = false;
        }
        if (pic->getX() <= -1){
            up = true;
        }

        if (up){
            pic->setX(pic->getX() + 0.05);

        }
        else if(!up){
            pic->setX(pic->getX() - 0.05);
        }
    }
    if(circle){
        pic->setX((r*cos(theta) + cx)-0.125);
        pic->setY((r*sin(theta) + cy)+0.125);
        theta += inc;
    }
    redraw();
}

void App::keyDown(unsigned char key, float x, float y){
    if (key == 27){
        exit(0);
    }
    if (key == ' '){
        animating = !animating;
    }
    else if (key == 'f'){
        toggleFullScreen();
    }
    else if (key == 'z'){
        circle = !circle;
    }
    redraw();
}

App::~App(){    
    delete pic;
    delete text;
    delete btn0;
    delete btn1;
    delete cicl;
    std::cout << "Exiting..." << std::endl;
}

