int merge(int x,int y) {
	if(!x || !y) return x | y;
	if(T[x].val > T[y].val) std::swap(x,y);
	T[x].ch[1] = merge(T[x].ch[1],y);
	if(T[T[x].ch[1]].dist > T[T[x].ch[0]].dist)
		std::swap(T[x].ch[0],T[x].ch[1]);
	T[x].dist = T[T[x].ch[1]].dist + 1;
	return x;
}

