{
  const char* precipsOut = argv[1];
  const char* tempsOut = argv[2];

  double lat0 = atof(argv[3]);
  double lon0 = atof(argv[4]);

  DividedRange latitudes = DividedRange::withEnds(29.625, 33.875, .25, Inds::lat);
