                                                                                                                      DividedRange::toTime(2010, 12, 31), // 2011, 1, 1
                                                                                                                      DividedRange::toTimespan(1).getValue(), Inds::unixtime),
                                                                           "../bhakra/mergeprecip.tsv",
                                                                           "../bhakra/mergeprecip_conf.tsv", NULL, '\t');

