{
    ExtendedOpenCDMSessionExt* sessionExt = static_cast<ExtendedOpenCDMSessionExt*>(mOpenCDMSession);

    return (OpenCDMError)sessionExt->StoreLicenseData(
        licenseData, licenseDataSize, secureStopId);
