//
// Date and time utility functions
//

#include "config.h"
#include "misc.h"

#include <sys/types.h>
#include <sys/time.h>
#include <time.h>
#ifdef HAVE_FTIME
#include <sys/timeb.h>
#endif

// Return the date. Return value is static data.
//
char *
datestring()
{
#ifdef HAVE_GETTIMEOFDAY
    struct timeval tv;
    gettimeofday(&tv, 0);
    struct tm *tp = localtime((time_t *) &tv.tv_sec);
    char *ap = asctime(tp);
#else
    time_t tloc;
    time(&tloc);
    struct tm *tp = localtime(&tloc);
    char *ap = asctime(tp);
#endif

    static char tbuf[40];
    strcpy(tbuf,ap);
    int i = strlen(tbuf);
    tbuf[i - 1] = '\0';
    return (tbuf);
}


// Return the elapsed time in milliseconds from the first call.
//
unsigned long
millisec()
{
    static long long init_time;
    unsigned long elapsed = 0;
#ifdef HAVE_GETTIMEOFDAY
    struct timeval tv;
    gettimeofday(&tv, 0);
    if (!init_time)
        init_time = ((long long)tv.tv_sec)*1000 + tv.tv_usec/1000;
    else
        elapsed = ((long long)tv.tv_sec)*1000 + tv.tv_usec/1000 - init_time;
#else
#ifdef HAVE_FTIME
    struct timeb tb;
    ftime(&tb);
    if (!init_time)
        init_time = ((long long)tb.time)*1000 + tb.millitm;
    else
        elapsed = ((long long)tb.time)*1000 + tb.millitm - init_time;
#else
    NO TIMER PACKAGE
#endif
#endif
    return (elapsed);
}


// How many seconds have elapsed since epoch.
//
double
seconds()
{
#ifdef HAVE_GETTIMEOFDAY
    struct timeval tv;
    gettimeofday(&tv, 0);
    return (tv.tv_sec + tv.tv_usec/1000000.0);
#else
#ifdef HAVE_FTIME
    struct timeb timenow;
    ftime(&timenow);
    return (timenow.time + timenow.millitm/1000.0);
#else
    // don't know how to do this in general.
    return (-1.0); // Obvious error condition
#endif
#endif
}

