using namespace std;
class Student
{
private:
	int num;
	char name[20];
	static int total;
public:

	Student()
	{
		total++;
	}
	Student(int n,char *p="wang");
	~Student()
	{
		total--;
	}
	void GetName();
	int GetNum();
};
int Student::total=0;
Student::Student(int n,char *p)
{
	num=n;
	strcpy(name,p);
	total++;
}
void Student::GetName()
{
	cout<<name<<endl;
}
int Student::GetNum()
{
	return num;
}
