typedef unsigned short qTable[64];

typedef struct
{
  struct tables
  {
    unsigned char size;
    unsigned char code;
  } small[512], large[65536];
} HuffTable;

void decodeHuffTable(int);

typedef struct
{
  HuffTable *huffAC, *huffDC;
  qTable *qTab;
  int dcPrev,smpx, smpy;
  float t[256];
}ComponentTable;

ComponentTable component[4];
HuffTable      huffTableAC[4],
huffTableDC[4];
