char fileOpen(const char *filename)
{
  FILE *stream;
  data = NULL;
  if ((stream=fopen(filename, "rb"))==NULL)
    return 0;
  else
  {
    fseek(stream, 0, SEEK_END);
    bsize = ftell(stream);
    fseek(stream, 0, SEEK_SET);
    data = new unsigned char[bsize];
    fread(data, 1, bsize, stream);
    fclose(stream);
    return 1;
  }
}

void fileClose(void)
{
  if (data)
    delete[] data;
}

unsigned char getByte(void)
{
  if (bpos>=dend)
  {
    eof = 1;
    return 0;
  }
  else
    return *bpos++;
}

void strmSkip(int n)
{
  unsigned char a, b;
  bfree+=n;
  dt<<=n;

  while (bfree>=8)
  {
    bfree-=8;
    b = getByte();
    if (b==255)
      a=getByte();
    dt|=(b<<bfree);
  }
}

int huffDec(HuffTable *h)
{
  unsigned int id, n, c;

  id = (dt>>(23));
  n  = h->small[id].size;
  c  = h->small[id].code;

  if (n==255)
  {
    id = (dt>>(16));
    n  = h->large[id].size;
    c  = h->large[id].code;
  }

  strmSkip(n);
  return c;
}

int wordDec(int n)
{
  int w;
  unsigned int s;

  if (n==0)
    return 0;
  else
  {
    s= (dt>>(31));
    w= (dt>>(32-n));
    strmSkip(n);
    if (s==0)
      w = (w|(0xffffffff<<n))+1;
  }
  return w;
}

void Image::getJPGInfo()
{
  unsigned char cn, sf, qt;
  int i;

  prec = getByte();

  if (prec!=8)
    return;

  height = ((getByte()<<8)+getByte());
  width  = ((getByte()<<8)+getByte());
  ncomp  = getByte();

  if ((ncomp!=3)&&(ncomp!=1))
    return;

  for (i=0;i<ncomp;i++)
  {
    cn = getByte();
    sf = getByte();
    qt = getByte();

    component[cn-1].qTab = &qtable[qt];
    component[cn-1].smpy = sf&15;
    component[cn-1].smpx = (sf>>4)&15;
  }

  if (component[0].smpx == 1)
    blockx = 8;
  else
    blockx = 16;

  if (component[0].smpy==1)
    blocky = 8;
  else
    blocky = 16;

  xblock=width/blockx;

  if ((width & (blockx-1))!=0)
    xblock++;

  yblock = height/blocky;

  if ((height&(blocky-1))!=0)
    yblock++;
}

void decodeHuffTable(int len)
{
  int length[257], i, j, n, code, codelen, delta, rcode, cd, rng;
  unsigned char lengths[16], b, symbol[257];
  HuffTable *h;

  len-=2;

  while (len>0)
  {
    b = getByte();
    len--;
    h = &huffTableDC[0];

    switch (b)
    {
      case 0:
        h = &huffTableDC[0];
        break;

      case 1:
        h = &huffTableDC[1];
        break;

      case 16:
        h = &huffTableAC[0];
        break;

      case 17:
        h=&huffTableAC[1];
        break;
    }

    for (i=0;i<16;i++)
      lengths[i] = getByte();

    len -= 16;
    n    =  0;

    for (i=0;i<16;i++)
    {
      len-=lengths[i];
      for (j=0;j<lengths[i];j++)
      {
        symbol[n]   = getByte();
        length[n++] = i+1;
      }
    }

    code = 0;
    codelen = length[0];

    for (i=0;i<n;i++)
    {

      rcode = code<<(16-codelen);
      cd = rcode>>7;

      if (codelen<=9)
      {
        rng = 1 <<(9-codelen);

        for (j=cd;j<cd+rng;j++)
        {
          h->small[j].code = (unsigned char)symbol[i];
          h->small[j].size = (unsigned char)codelen;
        }
      }
      else
      {
        h->small[cd].size=(unsigned char)255;
        rng = 1<<(16-codelen);

        for (j=rcode;j<rcode+rng;j++)
        {
          h->large[j].code=(unsigned char)symbol[i];
          h->large[j].size=(unsigned char)codelen;
        }
      }

      code++;
      delta=length[i+1]-codelen;
      code<<=delta;
      codelen+=delta;
    }
  }
}

void fidct(void)
{
  float a = 0.353553385f,
            b = 0.490392625f,
                c = 0.415734798f,
                    d = 0.277785122f,
                        e = 0.097545162f,
                            f = 0.461939752f,
