                                    cd =0.6935199499f,
                                        be =0.5879377723f,
                                            bc =0.9061274529f,
                                                de =0.3753302693f,
                                                    a0, f2, g2, a4, f6, g6, s0, s1, s2, s3,
                                                    t0, t1, t2, t3, m0, m1, m2, m3,
                                                    h0, h1, h2, h3, r0, r1, r2, r3, w;
  int i;

  for (i=0;i<64;i+=8)
  {
    if ((dctt[i+1]!=0)||(dctt[i+2]!=0)||(dctt[i+3]!=0)||(dctt[i+4]!=0)||(dctt[i+5]!=0)||(dctt[i+6]!=0)||(dctt[i+7]!=0))
