void decodeQTable(int len)
{
  int i;
  unsigned char b;

  len-=2;

  while (len>0)
  {
    b = (unsigned char)getByte();
    len--;

    if ((b&16)==0)
    {
      for (i=0;i<64;i++)
        qtable[b&15][i]=getByte();
      len-=64;
    }
    else
    {
      for (i=0;i<64;i++)
        qtable[b&15][i]=((getByte()<<8)+getByte());
      len-=128;
    }
  }
}

void decodeBlock(void)
{
  int compn, i, j, b, p, codelen, code, cx, cy, otab[64];
  qTable *qtab;

  for (compn=0;compn<ncomp;compn++)
  {
    qtab = component[compn].qTab;

    for (cy=0;cy<component[compn].smpy;cy++)
    {
      for (cx=0;cx<component[compn].smpx;cx++)
      {
        for (i=0;i<64;i++)
          otab[i]=0;

        codelen= huffDec(component[compn].huffDC);
        code=wordDec(codelen);

        otab[0] = code+component[compn].dcPrev;
        component[compn].dcPrev = otab[0];
        i=1;

        while (i<64)
        {
          codelen=huffDec(component[compn].huffAC);
          if (codelen==0)
            i=64;
          else
            if (codelen==0xf0)
              i+=16;
            else
            {
              code = wordDec(codelen&15);
              i = i+(codelen>>4);
              otab[i++]=code;
            }
        }

        for (i=0;i<64;i++)
          dctt[zigzag[i]]=(float)((*qtab)[i]*otab[i]);

        fidct();
        b=(cy<<7)+(cx<<3);
        p=0;

        for (i=0;i<8;i++)
        {
          for (j=0;j<8;j++)
            component[compn].t[b++]=dctt[p++]+128;
          b+=8;
        }
      }
    }
  }
}

int Image::decodeScanJPG()
{
  int nnx, nny, i, j;
  int xmin, ymin, xmax, ymax, blockn, adr1, adr2;
  int y1, u1, v1, y2, u2, v2, u3, v3;
  int dux, duy, dvx, dvy;
  unsigned char sc, ts;
  float cy, cu, cv;
  components = int(getByte());

  setFormat(GL_BGR);
  setInternalFormat(GL_RGB8);

  if (dataBuffer)
    deleteArray(dataBuffer);

  dataBuffer = new GLubyte[width*height*components];

  for (i=0;i<components;i++)
  {
    sc = getByte();
    ts = getByte();

    component[sc-1].huffDC = &huffTableDC[ts>>4];
    component[sc-1].huffAC = &huffTableAC[ts&15];
  }

  ssStart = getByte();
  ssEnd   = getByte();
  sbits   = getByte();

  if ((ssStart!=0)||(ssEnd!=63))
    return 0;

  if (components == 3)
  {
    dux = 2+component[1].smpx-component[0].smpx;
    duy = 2+component[1].smpy-component[0].smpy;
    dvx = 2+component[2].smpx-component[0].smpx;
    dvy = 2+component[2].smpy-component[0].smpy;
  }

  dt    = 0;
  bfree = 0;
  strmSkip(32);

  blockn=0;
  ymin=0;

  for (nny=0;nny<yblock;nny++)
  {
    ymax = ymin+blocky;

    if (ymax>height)
      ymax = height;

    xmin=0;

    for (nnx=0;nnx<xblock;nnx++)
    {
      xmax=xmin+blockx;

      if (xmax>width)
        xmax=width;

      decodeBlock();

      blockn++;
      if ((blockn==restartInt)&&((nnx<xblock-1)||(nny<yblock-1)))
      {
        blockn=0;

        if (bfree!=0)
          strmSkip(8-bfree);

        if (wordDec(8)!=255)
          return 0;

        for (i=0;i<components;i++)
          component[i].dcPrev=0;
      }

      if (components ==3)
      {
        y1=u1=v1=0;
        adr1=(height-1-ymin)*width+xmin;

        for (i=ymin;i<ymax;i++)
        {
          adr2=adr1;
          adr1-=width;
          y2=y1;
          y1+=16;
          u3=(u1>>1)<<4;
          u1+=duy;
          v3=(v1>>1)<<4;
          v1+=dvy;
          u2=v2=0;

          for (j=xmin;j<xmax;j++)
          {
            int cr, cg, cb;
            cy=component[0].t[y2++];
            cu=component[1].t[u3+(u2>>1)]-128.0f;
            cv=component[2].t[v3+(v2>>1)]-128.0f;

            cr=(int)(cy+1.402f*cv);
            cg=(int)(cy-0.34414f*cu-0.71414f*cv);
            cb=(int)(cy+1.772f*cu);

            dataBuffer[3*adr2]   = max(0, min(255, cb));
            dataBuffer[3*adr2+1] = max(0, min(255, cg));
            dataBuffer[3*adr2+2] = max(0, min(255, cr));
            adr2++;

            u2+=dux;
            v2+=dvx;
          }
        }
      }
      else
        if (components==1)
        {
          y1=0;
          adr1=(height-1-ymin)*width+xmin;

          for (i=ymin;i<ymax;i++)
          {
            adr2=adr1;
            adr1-=width;
            y2=y1;
            y1+=16;

            for (j=xmin;j<xmax;j++)
            {
              int lum=(int)component[0].t[y2++];
              dataBuffer[adr2++]=max(0, min(255, lum));
            }
          }
        }
      xmin=xmax;
    }
    ymin=ymax;
  }
  return 1;
}

int Image::decodeJPG()
{
  int w;
  unsigned char a, hdr=0, scan=0;

  eof=0;
  bpos=data;
  dend=bpos+bsize;
  w=((getByte()<<8)+getByte());

  if (w!=0xffd8)
    return 0;

  while (eof==0)
  {
    a=(unsigned char)getByte();

    if (a!=0xff)
      return 0;

    a=(unsigned char)getByte();
    w=((getByte()<<8)+getByte());

    switch (a)
    {
      case 0xe0:
        if (hdr!=0)
          break;

        if (getByte()!='J')
          return 0;

        if (getByte()!='F')
          return 0;

        if (getByte()!='I')
          return 0;

        if (getByte()!='F')
          return 0;

        hdr=1;
        w-=4;
        break;

      case 0xc0:
        getJPGInfo();
        w=0;
        break;

      case 0xc4:
        decodeHuffTable(w);
        w=0;
        break;

      case 0xd9:
        w=0;
        break;

      case 0xda:
        if (scan!=0)
          break;

        scan=1;

        if (!decodeScanJPG())
          return 0;

        w=0;
        eof=1;
        break;

      case 0xdb:
        decodeQTable(w);
        w=0;
        break;

      case 0xdd:
        restartInt=((getByte()<<8)+getByte());
        w=0;
        break;
    }

    while (w>2)
    {
      getByte();
      w--;
    }
  }
  return 1;
}

bool Image::loadJPG(const char *filename)
{
  int i;
  for (i=0;i<4;i++)
    component[i].dcPrev=0;

  restartInt=-1;

  if (fileOpen(filename))
  {
    int ret= decodeJPG();
    fileClose();
    if (!ret)
      return false;
    return true;
  }
  else
    return false;
}

