};


// --- BarControl ------------------------------------------------------------------------------

void load_BarControl(py::module m) {
	// --- BarControl --------------------------------------------------------------------------
	py::class_<BarControl, Item>(m, "BarControl")
		.def("SetMin", &BarControl::SetMin)
		.def("SetMax", &BarControl::SetMax)
		.def("SetValue", &BarControl::SetValue)
		.def("GetMin", &BarControl::GetMin)
