    //native_window_api_connect(window, frame.api_type);
    // exclude LayerDim
    for (int i = 1; i < FRAME_COUNT; i++) {
        surface_utils[i].connectAPI(NATIVE_WINDOW_API_CPU);
    }

    // initialize input frames
    initFrames();

    // display
    int loop = 0;
    while (true) {
        // surface 2 ~
        for (int i = 1; i < FRAME_COUNT; i++) {
            // show frame
            surface_utils[i].showTestFrame(&frames[0], i % 4);
