void Tracer(LPCSTR format, ...)
{
    if (format)
    {
        va_list vl;
        char str[4096];

        va_start(vl, format);
        _vsnprintf(str, (sizeof(str) - 1), format, vl);
        str[(sizeof(str) - 1)] = 0;
        va_end(vl);

        // Output to debugger channel
        OutputDebugString(str);
        printf(str);
    }
}

#ifdef _DEBUG
