void split(const string &s, const char* delim, vector<string> & v) {
	char * dup = strdup(s.c_str());
	char * token = strtok(dup, delim);
	while (token != NULL)
		v.push_back(string(token)), token = strtok(NULL, delim);
	free(dup);
}
