using namespace std;
vector< vector<int> > adm,radm;
vector<int> sorted;
set<int> visited;

void dfs1(int node)
{
    visited.insert(node);
    for(auto x: adm[node])
    {
        if(!visited.count(x))
        {
            dfs1(x);
        }
    }
    sorted.push_back(node);
}

void dfs2(int node)
{
    cout<<node<<" ";
    visited.insert(node);
    for(auto x: radm[node])
    {
        if(!visited.count(x))
        {
            dfs2(x);
        }
    }
}

