{

    freopen("input.txt", "r", stdin);
    int n,m;
    cin>>n>>m;
    adm.resize(n+1);
    radm.resize(n+1);

    for(int i=0;i<m;i++)
    {
        int x,y;
        cin>>x>>y;
        adm[x].push_back(y);
        radm[y].push_back(x);
    }

    for(int i=1;i<=n;i++)
    {
        if(!visited.count(i))
        {
            dfs1(i);
        }
    }

    visited.clear();

    reverse(sorted.begin(), sorted.end());

    for(auto node: sorted)
    {
        if(!visited.count(node))
        {
            dfs2(node);
            cout<<endl;
        }

    }


}

