void search(char* target, vector<string>* results, char* path){
#ifdef ESP32
  File fp;
#else
  FILE* fp;
#endif
  const size_t line_size = 1024;
  char line[1024];
  char* linePtr = line; // TODO: more smart way?
  char* targetPtr = target;
#ifdef ESP32
  fp = SPIFFS.open(path, "r");
#else
  fp = fopen(path, "r");
#endif
