struct state_cmp {
    bool operator() (const state& lhs, const state& rhs) const {
        if (lhs.f == rhs.f) return rhs.heuristic < lhs.heuristic;
        else return lhs.f < rhs.f;
    }
};

ull generate_hash_key(int board [][4]){
    ull hash_key = 0;
    int count = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            ull input = board[i][j];
            hash_key += input << (count * 4);
            count++;
        }
    }
    return hash_key;
}

