class Timer {
	public:
		Timer(float sampleRate)
		: _ticks(0),
		  _seconds(0.0),
		  _sampleRate(sampleRate)
		{}

		float seconds() const {
			return _seconds;
		}

		unsigned long int ticks() const {
			return _ticks;
