	packet[5] = AX_PRESENT_TEMPERATURE;
	packet[6] = AX_BYTE_READ;
	packet[7] = Checksum;

	sendAXPacketNoError(packet, length);

	Temperature_Byte = -1;
	Time_Counter = 0;
	while ((availableData() < 6) & (Time_Counter < TIME_OUT))
	{
		Time_Counter++;
		delayus(1000);
	}

	while (availableData() > 0)
	{
		Incoming_Byte = readData();
