   TileMapHandler& mapHandler = 
      *app->getDrawingArea()->getTileMapHandler();

   MC2Point inarg(0, 0);
   mapHandler.transform(inarg, mapHandler.getCenter());

   vicVec_t crossings;

   if(app->shouldDetectAlongTheRoad() && app->hasRoad()) {
      mapHandler.getCrossingsAlongRoad(inarg,
