void test_stack() {
	Memory m;
	uint8_t sp = 0xa0, ret = 0x0;

	m.push_stack(sp, 0xb1);
	m.push_stack(sp, 0xb2);
	assert(sp == 0xa2);
	assert(m[0x1ff - 0xa0] == 0xb1);
	assert(m[0x1ff - 0xa1] == 0xb2);

	ret = m.pop_stack(sp);
	assert(ret == 0xb2);
	assert(sp == 0xa1);
	assert(m[0x1ff - 0xa0] == 0xb1);
}

