	void test_eor(Instruction& eor, CPU& cpu, Memory& mem) {
		// exclusive or with accumulator (A = A ^ M)

		// non-zero, non-negative
		cpu.pc = 0x33;
		cpu.acc = 0xb5;			// 10110101
		mem[cpu.pc + 1] = 0x22;
		mem[cpu.pc + 2] = 0x44;
		mem[0x4422] = 0x88;		// 10001000
		eor(cpu, mem);
		assert(cpu.acc == 0x3d);// 00111101
		assert(!cpu.p_n());
		assert(!cpu.p_z());

		// non-zero, negative
		cpu.pc = 0x33;
		cpu.acc = 0xb5;			// 10110101
		mem[cpu.pc + 1] = 0x22;
		mem[cpu.pc + 2] = 0x44;
		mem[0x4422] = 0x68;		// 01101000
		eor(cpu, mem);
		assert(cpu.acc == 0xdd);// 11011101
		assert(cpu.p_n());
		assert(!cpu.p_z());

		// zero, non-negative
		cpu.pc = 0x33;
		cpu.acc = 0xb5;			// 10110101
		mem[cpu.pc + 1] = 0x22;
		mem[cpu.pc + 2] = 0x44;
		mem[0x4422] = 0x68;		// 01101000
		eor(cpu, mem);
		assert(cpu.acc == 0xdd);// 11011101
		assert(cpu.p_n());
		assert(!cpu.p_z());
	}

	void test_and(Instruction& _and, CPU& cpu, Memory& mem) {
		// AND value pointed to in memory with the accumulator
		cpu.pc = 0x33;
		cpu.acc = 0xcc; // 11001100
		mem[cpu.pc + 1] = 0x22;
		mem[cpu.pc + 2] = 0x44;
		mem[0x4422] = 0xaa; // 10101010
		_and(cpu, mem);
		// result should be 10001000 (0x88)
		assert(cpu.acc == 0x88);
		assert(cpu.p_n());
		assert(!cpu.p_z());
	}

	void test_cpx(Instruction& cpx, CPU& cpu, Memory& mem) {
		// set flags depending on the comparison of Y and the value pointed to in memory
		// X < M
		cpu.pc = 0x21;
		cpu.x = 0x33;
		mem[cpu.pc + 1] = 0x22; // lo
		mem[cpu.pc + 2] = 0x33; // hi
		mem[0x3322] = 0x55;
		cpx(cpu, mem);
		assert(cpu.pc == 0x24);
		assert(cpu.p_n());
		assert(!cpu.p_z());
		assert(!cpu.p_c());

		// X >= M
		cpu.pc = 0x21;
		cpu.x = 0x66;
		mem[cpu.pc + 1] = 0x22; // lo
		mem[cpu.pc + 2] = 0x33; // hi
		mem[0x3322] = 0x33;
		cpx(cpu, mem);
		assert(cpu.pc == 0x24);
		assert(!cpu.p_n());
		assert(!cpu.p_z());
		assert(cpu.p_c());

		// X == M
		cpu.pc = 0x21;
		cpu.x = 0x55;
		mem[cpu.pc + 1] = 0x22; // lo
		mem[cpu.pc + 2] = 0x33; // hi
		mem[0x3322] = 0x55;
		cpx(cpu, mem);
		assert(cpu.pc == 0x24);
		assert(!cpu.p_n());
		assert(cpu.p_z());
		assert(cpu.p_c());
	}

