		tsx(cpu, mem);
		assert(cpu.x == cpu.sp);
	}

	void test_dex(Instruction& dex, CPU& cpu, Memory& mem) {
		cpu.x = 0x11;
		dex(cpu, mem);
		assert(cpu.x == 0x10);
		assert(!cpu.p_n());
		assert(!cpu.p_z());

		cpu.x = 0x81;
		dex(cpu, mem);
		assert(cpu.x == 0x80);
		assert(cpu.p_n());
		assert(!cpu.p_z());

		cpu.x = 0x01;
		dex(cpu, mem);
		assert(cpu.x == 0x00);
		assert(!cpu.p_n());
		assert(cpu.p_z());
	}

	void test_nop(Instruction& nop, CPU& cpu, Memory& mem) {
		CPU tempCPU = CPU(cpu);
		nop(cpu, mem);
		assert(cpu.acc == tempCPU.acc);
		assert(cpu.pc == tempCPU.pc + 1);
		assert(cpu.sp == tempCPU.sp);
		assert(cpu.x == tempCPU.x);
		assert(cpu.y == tempCPU.y);
		assert(cpu.p == tempCPU.p);
	}

	void test_sed(Instruction& sed, CPU& cpu, Memory& mem) {
		cpu.p_d(false);
		sed(cpu, mem);
		assert(cpu.p_d());
	}

	void test_inx(Instruction& inx, CPU& cpu, Memory& mem) {
		cpu.x = 0x77;
		inx(cpu, mem);
		assert(cpu.x == 0x78);
		assert(!cpu.p_n());
		assert(!cpu.p_z());

		cpu.x = 0xff;
		inx(cpu, mem);
		assert(cpu.x == 0x00);
		assert(!cpu.p_n());
		assert(cpu.p_z());

		cpu.x = 0x7f;
		inx(cpu, mem);
		assert(cpu.x == 0x80);
		assert(cpu.p_n());
		assert(!cpu.p_z());
	}

	void test_cld(Instruction& cld, CPU& cpu, Memory& mem) {
		cpu.p_d(true);
		cld(cpu, mem);
		assert(!cpu.p_d());
	}

	void test_iny(Instruction& iny, CPU& cpu, Memory& mem) {
		cpu.y = 0x77;
		iny(cpu, mem);
		assert(cpu.y == 0x78);
		assert(!cpu.p_n());
		assert(!cpu.p_z());

		cpu.y = 0xff;
		iny(cpu, mem);
		assert(cpu.y == 0x00);
		assert(!cpu.p_n());
		assert(cpu.p_z());

		cpu.y = 0x7f;
		iny(cpu, mem);
		assert(cpu.y == 0x80);
		assert(cpu.p_n());
		assert(!cpu.p_z());
	}

	void test_clv(Instruction& clv, CPU& cpu, Memory& mem) {
		cpu.p_v(true);
		clv(cpu, mem);
		assert(!cpu.p_v());
	}

	void test_tay(Instruction& tay, CPU& cpu, Memory& mem) {
		cpu.acc = 0x10;
		cpu.y = 0x20;
		tay(cpu, mem);
		assert(cpu.y == cpu.acc);
		assert(!cpu.p_z());
		assert(!cpu.p_n());

		cpu.acc = 0x00;
		cpu.y = 0x20;
		tay(cpu, mem);
		assert(cpu.acc == cpu.y);
		assert(cpu.p_z());
		assert(!cpu.p_n());

		cpu.acc = 0x80;
		cpu.y = 0x20;
		tay(cpu, mem);
		assert(cpu.acc == cpu.y);
		assert(cpu.p_n());
		assert(!cpu.p_z());
	}

	void test_tya(Instruction& tya, CPU& cpu, Memory& mem) {
		cpu.y = 0x10;
		cpu.acc = 0x20;
		tya(cpu, mem);
		assert(cpu.acc == cpu.y);
		assert(!cpu.p_z());
		assert(!cpu.p_n());

		cpu.y = 0x00;
		cpu.acc = 0x20;
		tya(cpu, mem);
		assert(cpu.acc == cpu.y);
		assert(cpu.p_z());
		assert(!cpu.p_n());

		cpu.y = 0x80;
		cpu.acc = 0x20;
		tya(cpu, mem);
		assert(cpu.acc == cpu.y);
		assert(cpu.p_n());
		assert(!cpu.p_z());
	}

	void test_dey(Instruction& dey, CPU& cpu, Memory& mem) {
		cpu.y = 0x10;
		dey(cpu, mem);
		assert(cpu.y == 0x0f);
		assert(!cpu.p_z());
		assert(!cpu.p_n());

		cpu.y = 0x01;
		dey(cpu, mem);
		assert(cpu.y == 0);
		assert(cpu.p_z());
		assert(!cpu.p_n());

		// test when the value is negative (I think it still straight decrements?)
		// 10000001 => 10000000 (0x81 -> DEY -> 0x80)
		cpu.y = 0x81;
		dey(cpu, mem);
		assert(cpu.y == 0x80);
		assert(!cpu.p_z());
		assert(cpu.p_n());
	}

	void test_sei(Instruction& sei, CPU& cpu, Memory& mem) {
		cpu.p_i(false);
		sei(cpu, mem);
		assert(cpu.p_i());
	}

	void test_pla(Instruction& pla, CPU& cpu, Memory& mem) {
		cpu.acc = 0x77;
		cpu.sp = 0x02;
		mem[0x1fe] = 0x66;
		pla(cpu, mem);
		assert(cpu.acc == 0x66);
		assert(cpu.sp == 0x01);
	}

	void test_cli(Instruction& cli, CPU& cpu, Memory& mem) {
		cpu.p_i(true);
		cli(cpu, mem);
		assert(!cpu.p_i());
	}

	void test_pha(Instruction& pha, CPU& cpu, Memory& mem) {
		cpu.acc = 0x66;
		cpu.sp = 0;
		mem[0x1ff] = 0x00;
		pha(cpu, mem);
		assert(mem[0x1ff] == cpu.acc);
	}

	void test_sec(Instruction& sec, CPU& cpu, Memory& mem) {
		cpu.p_c(false);
		sec(cpu, mem);
		assert(cpu.p_c());
	}

	void test_plp(Instruction& plp, CPU& cpu, Memory& mem) {
		cpu.p = 0x70;
		cpu.sp = 0x44;
		mem.push_stack(cpu.sp, 0x10);
		plp(cpu, mem);
		assert(cpu.p == 0x10);
		assert(cpu.sp == 0x44);
	}

	void test_php(Instruction& php, CPU& cpu, Memory& mem) {
		// PHP: push the status register onto the stack
		cpu.sp = 0;
		cpu.p = 0x70;
		assert(mem[0x1ff] != cpu.p);
		php(cpu, mem);
		assert(cpu.sp == 1);
		assert(mem[0x1ff] == cpu.p);
		php(cpu, mem);
		php(cpu, mem);
		assert(cpu.sp == 3);
		assert(mem[0x1fe] == cpu.p);
		assert(mem[0x1fd] == cpu.p);
	}

	void test_clc(Instruction& clc, CPU& cpu, Memory& mem) {
		// CLC: clear the carry flag on the status register
		cpu.p_c(true);
		clc(cpu, mem);
		assert(!cpu.p_c());
		cpu.p_c(false);
		clc(cpu, mem);
		assert(!cpu.p_c());
	}

}

int do_asm_tests() {
	cout << "Running tests" << endl;

	Assembler assembler;

	vector<unsigned char> result;
	string resultstr;

	result = assembler.decodeline(string("BRK"));
	resultstr = make_string(result);
	assert(resultstr == string("00"));

	result = assembler.decodeline(string("BPL $00"));
	resultstr = make_string(result);
	assert(resultstr == string("10FD"));

	result = assembler.decodeline(string("BPL $10"));
	resultstr = make_string(result);
	assert(resultstr == string("100B"));

	return 0;
}

string make_string(vector<unsigned char>& in) {
	ostringstream ss;

	for (auto c : in) {
		if (c < 10) ss << '0';
		ss << hex << (int) c;
	}

	return ss.str();
}


