#define __db_con_pool_size      16


using namespace std;
using namespace handy;
using namespace nlohmann;


typedef struct db_con_pool_ {
    std::unique_ptr<sql::Connection> con;
    std::unique_ptr<sql::Statement> stmt;
}db_con_pool_t;


int main(int argc, const char *argv[]) {

    if (argc < 5){
        info("./server ipaddr port user password");
        return 0;
    }


    sql::Driver *driver;

    unsigned int reader = 0;
    unsigned int writer = __db_con_pool_size;
    std::mutex db_con_mtx;
    std::condition_variable db_con_cv;
    vector<shared_ptr<db_con_pool_t>> db_con_pool(__db_con_pool_size);

    string ip = string(argv[1]).append(":").append(argv[2]);
    string user = argv[3];
    string password = argv[4];

    setloglevel("TRACE");

	try
	{
        driver = get_driver_instance();

        for (int i = 0; i < db_con_pool.size(); ++i){
            db_con_pool[i].reset(new db_con_pool_t);
            db_con_pool[i]->con.reset(driver->connect(ip, user, password));
            db_con_pool[i]->con->setSchema(user);
            db_con_pool[i]->stmt.reset(db_con_pool[i]->con->createStatement());
        }

	}
	catch (sql::SQLException e)
	{
        error("Could not connect to server. Error message: %s\n", e.what());
		exit(1);
	}

    map<intptr_t, TcpConnPtr> users;  //生命周期比连接更长，必须放在Base前
    EventBase base;
    Signal::signal(SIGINT, [&] { base.exit(); });

    int userid = 1;
    TcpServerPtr chat = TcpServer::startServer(&base, "", 2099);
    exitif(chat == NULL, "start tcpserver failed");
    chat->onConnCreate([&] {
        TcpConnPtr con(new TcpConn);
        con->onState([&](const TcpConnPtr &con) {
            if (con->getState() == TcpConn::Connected) {
                con->context<int>() = userid;
                json js;
                js["version"] = 0.001;
                string s = js.dump();
                con->sendMsg(s);
                users[userid] = con;
                userid++;
            } else if (con->getState() == TcpConn::Closed) {
                users.erase(con->context<int>());
            }
        });
        con->onMsg(new LengthCodec, [&](const TcpConnPtr &con, Slice msg) {
            if (msg.size() == 0) {  //忽略空消息
                return;
            }
            int cid = con->context<int>();
            info("%s\n", msg.data());
            try
            {
                json js = json::parse(msg.data());
                string s = js.dump();
                con->sendMsg(s);
            }
            catch(const std::exception& e)
            {
                con->sendMsg("!!format error!!");
            }

            shared_ptr<db_con_pool_t> db_con;
            {
                std::unique_lock<std::mutex> lock(db_con_mtx);
                while (writer - reader == 0){
                    db_con_cv.wait(lock);
                }
                db_con = db_con_pool[reader & ( __db_con_pool_size - 1 )];
                reader ++;
            }

            std::unique_ptr< sql::ResultSet > res(db_con->stmt->executeQuery("SELECT * FROM appNavi"));
            while (res->next())
            {
                info("key: %s\n", res->getString(1).c_str());
                // info("value:\n %s\n", json::parse(res->getString(2).c_str()).dump(4).c_str());
                info("db con address %p\n", db_con.get());
            }

            {
                std::unique_lock<std::mutex> lock(db_con_mtx);
                writer ++;
                db_con_cv.notify_all();
            }

        });
        return con;
    });
    base.loop();

    info("program exited");
    return 0;
}

