    deque<char> d;
    d.push_front(s[0]);
    for (int i = 1; i < s.size(); i++) {
      // Compare the two deques
      deque<char> front(d);
      front.push_front(s[i]);
      deque<char> back(d);
      back.push_back(s[i]);

