  if (g_verbose == 1)
    printf("-------------------------Initializing-------------------------\n");
  //verify the password 
  if (g_as608.has_password) {
    if (!PS_VfyPwd(password))
     return false;
  }

  // obtain the size of datapack and the baud rate ec.
  if (PS_ReadSysPara() && g_as608.packet_size > 0) {
    if (g_verbose == 1)
      printf("-----------------------------Done-----------------------------\n");
    return true;
  }

  if (g_verbose == 1)
    printf("-----------------------------Done-----------------------------\n");
  g_error_code = 0xC7;
  return false;
}


