      "\n Z Force    FZ:  %7.1f N"
      "\n Side Force FY:  %7.1f N"
      "\n Roll Mom   MZ:  %7.1f Nm"
      "\n Pitch Mom  MY:  %7.1f Nm \n\n",
      FLAGS_v_axial, FLAGS_v_edgewise, FLAGS_omega, thrust, torque,
      z_force, side_force, roll_moment, pitch_moment);
}

