                                     FLAGS_v_edgewise, FLAGS_air_density,
                                     FLAGS_dir);

  // Print to screen.
  PrintRotorCoefficients(z_force, side_force, roll_moment, pitch_moment,
                         thrust, torque);

  return EXIT_SUCCESS;
}

