void gen_primes(vector<int>& cnt, int n) {
  vector<int> vis(n+1, 0);
  cnt.resize(n+1, 0);
  int p = 0;
  for(int i = 2; i <= n; ++i) if(!vis[i]) {
    cnt[i] = ++p; 
    for(int j = 2*i; j <= n; j += i) {
      cnt[j] = p;
      vis[j] = 1;
    }
  }
}


int main() {
  int n;
  vector<int> cnt;
  gen_primes(cnt, maxn);
  while(~scanf("%d\n", &n)) {
    printf("%d\n", cnt[n]);
  }
  return 0;
}

