 */
int smg$draw_line(
	struct ncurses_struct **display_id,
	int srow,
	int scolumn,
	int erow,
	int ecolumn)
{
	if (srow == erow)
	{
		mvwhline((*display_id)->win, srow, scolumn, 0, ecolumn - scolumn + 1);
	}
	else
	{
		mvwvline((*display_id)->win, srow, scolumn, 0, erow - srow + 1);
	}
	return 0;
}

