class Solution
{
public:
    void reverseString(vector<char> inputString)
    {
        for (int i = 0, j = inputString.size() - 1; i < j; i++, j--)
        {
            char temp = inputString[i];
            inputString[i] = inputString[j];
            inputString[j] = temp;
        }
    }
};

int main()
{
