    int numberOfElement = sizeof(inputString) / sizeof(inputString[0]);

    std::vector<char> string(numberOfElement);
    memcpy(&string[0], &inputString[0], numberOfElement * sizeof(int));
    Solution solution;

    solution.reverseString(string);
}

