int combinationSum4(vector<int>& nums, int target) {

    sort(nums.begin(), nums.end());
    vector <int> res (target + 1, 0);
    for (int i = 1; i < res.size(); i++) {
        for (int x : nums) {
            if (x > i) break;
            else if (x == i) {
                res[i]++;
            } else {
                res[i] += res[i-x];
            }
        }
    }
    return res[target];
}


