			string sub = "";

			while (1)
			{
				int pos = path.find(ENTERLN);
				if (pos >= 0)
				{
					sub = path.substr(0, pos);
					path = path.substr(pos + strlen(ENTERLN));

					if (sub.back() != '\\')
					{
						sub.append("\\");
					}
				}
				else if (path.length() > 0)
				{
					sub = path;
					if (sub.back() != '\\')
