                while (spottedIndexInWindow < spotted.size && spotted.demoFile[spottedIndexInWindow] == position.demoFile[windowIndex] &&
                        spotted.demoTickNumber[spottedIndexInWindow] <= position.demoTickNumber[windowIndex]) {
