    ArrayHandle<Scalar> h_virial_3(virial_array_3,access_location::host,access_mode::read);
    MY_CHECK_CLOSE(h_force_3.data[0].x, 30.581156, tol);
    MY_CHECK_CLOSE(h_force_3.data[1].x, -30.581156, tol);
