unordered_set<int> numbers;

bool checkIfAllUnique(int n) {
    int unique = true;

    while (n / 10 > 0) {
        if (numbers.count(n % 10)) {
            unique = false;
        }
        else {
            numbers.insert(n % 10);
        }

        n /= 10;
    }

    if (numbers.count(n % 10)) {
        unique = false;
    }

    numbers.clear();

    return unique;
}

