	// LEDs
	addChild(createLight<MediumLight<GreenLight>>(Vec(46, 20), module, SharpWavefolder::BLINK_LIGHT));
	addChild(createLight<MediumLight<RedLight>>(Vec(46, 340), module, SharpWavefolder::OUTPUT_LIGHT));

}

