#include "zdk/string.h"
#define __USE_GNU
#include <ctype.h>


int strcmp_ignore_space(
    const char* __restrict p,
    const char* __restrict r
    )
{
    for (; *p; ++p)
    {
        if (isspace(*p))
        {
            continue;
        }
        else
        {
            if (*r == 0)
            {
                return 1; // p > r
            }
            while (isspace(*r))
            {
                ++r;
            }
        }
        if (*p < *r)
        {
            return -1;
        }
        if (*p > *r)
        {
            return 1;
        }
        if (*r)
        {
            ++r;
        }
    }
    while (isspace(*r))
    {
        ++r;
    }
    return *r == 0 ? 0 : -1;
}

