char&	    AppCUI::Utils::String::operator[] (int poz)
{
	if ((Text==nullptr) || (Size==0))
	{
        tempCharForReferenceReturn = 0;
        return	tempCharForReferenceReturn;
	}
    if (poz < 0)
        poz += (int)this->Size;
    if (((poz+1) > (int)Size) || (poz<0))
    {
        tempCharForReferenceReturn = 0;
        return	tempCharForReferenceReturn;
    }
    return Text[poz];
}

