#include <iostream>
using namespace std;

const int FIL=2;
const int COL=5;

void sumaIndice (int matriz[][COL],int FIL, int COL, int &suma, int &indice){

  int menor=matriz[0][0]+matriz[1][0];
  for(int i=0; i < COL;i++){
    suma=0;
    for(int j=0;j<FIL;j++){
      suma = suma + matriz[j][i];
    }
    cout<<"La suma de la columna es: "<<suma<<endl;
    if(menor > suma){
      menor = suma;
      indice = i;
    }
    suma=menor;
  }
}


