#ifdef LOCAL
#define dbg(args...) cerr<<"("<<#args<<") =", debug(args)
#else
#define dbg(args...) 2020
#endif
struct Tree {
    int n;
    vector<vector<int>> g;
    vector<int> sz, pa, depth, sta, fin, tour;
    int tim;
    RASQ<int> rasq;
    Tree(int _n) : n(_n)
        , g(n)
        , sz(n)
        , pa(n, -1)
        , depth(n)
        , sta(n)
        , fin(n)
        , rasq(n)
        , trk(n)
        {
        tour.reserve(n);
        input(); 
        tim = 1; basic_dfs(0);
        build_lca();
    }
    int L;
    vector<vector<int>> pa_up;
    void build_lca() {
        L = 0; while ((1<<L) < n-1) L++;
        pa_up = vector<vector<int>>(L+1, vector<int>(n));
        pa[0] = 0; // root-self
        for (int u: tour) {
            pa_up[0][u] = pa[u];
            for (int j = 1; j <= L; j++) {
                pa_up[j][u] = pa_up[j-1][ pa_up[j-1][u] ];
            }
        }
    }

    inline void add(int u, int v) {
        g[u].emplace_back(v);
        g[v].emplace_back(u);
    }
    void input() {
        for (int _ = 1; _ < n; _++) {
            int x,y;
            cin >> x >> y;
            --x; --y; // to 0-based
            add(x,y);
        }
    }
    void basic_dfs(int u) {
        if (pa[u] != -1) g[u].erase(find(g[u].begin(), g[u].end(), pa[u]));
        sta[u] = tim++;
        tour.emplace_back(u);
        for (int& v: g[u]) {
            pa[v] = u;
            depth[v] = depth[u] + 1;
            basic_dfs(v);
            sz[u] += sz[v];
        }
        ++sz[u];
        fin[u] = tim;
    }
    inline bool is_ancestor(int u, int v) {
        return sta[u] <= sta[v] && fin[v] <= fin[u];
    }
    inline int lca(int u, int v) {
        if (is_ancestor(u, v)) return u;
        if (is_ancestor(v, u)) return v;
        for (int j = L; j >= 0; j--) {
            if(!is_ancestor(pa_up[j][u], v))
                u = pa_up[j][u];
        }
        return pa_up[0][u];
    }
    int dist(int u, int v) {
        return depth[u] + depth[v] - 2*depth[lca(u,v)];
    }
    int goup(int u, int step) {
        for (int j = L; j >= 0; j--) {
            if (step>>j&1) u = pa_up[j][u];
        }
        return u;
    }

    vector<bool> trk;
    // the key is process by dfs order, the only needed info is how many ances of u.
    //   with reroot, which => path cnt(by BIT) + lca.
    void solve() {
        int k,m,r;
        cin >> k >> m >> r; r--;
        // by dfs order, relax-> depth order
        vector<int> a(k);
        vector<pair<int, int>> da(k);
        for (int i = 0; i < k; i++) {
            cin >> a[i]; --a[i];
            da[i] = {dist(a[i], r), a[i]};
        }
        sort(da.begin(), da.end());
        for (int i = 0; i < k; i++) {
            a[i] = da[i].second;
        }
        //sort(a.begin(), a.end(), [&](auto& u, auto& v){
        //    return dist(u,r) < dist(v,r);
        //});
dbg(a);
        // #trk[0..u]
        auto cnt0 = [&](int u){
            return rasq.query(sta[u]);
        };
        // #trk[r..u)
        auto cntr = [&](int u) {
            return cnt0(u) + cnt0(r) - 2*cnt0(lca(u,r)) + (int)(trk[lca(u,r)]) - 1;
        };
        vector<vector<mint>> dp(2, vector<mint>(m+2));
        dp[0][0] = 1;
        int crt = 0;
        for (int i = 0; i < k; i++) {
            int u = a[i]; trk[u] = true;
            rasq.add(sta[u], fin[u], 1);
            int x = cntr(u);
dbg(u, x);
            int nxt = crt ^ 1;
            fill(dp[nxt].begin(), dp[nxt].end(), 0);
            for (int j = 0; j <= i && j <= m; j++) {
                dp[nxt][j+1] += dp[crt][j];
                if (j>x)dp[nxt][j] += dp[crt][j] * (j - x);
            }
            crt ^= 1;
        }
        mint res = 0;
        for (int j = 1; j <= m; j++) {
            res += dp[crt][j];
        }
        cout << res << "\n";
        // reset
        for (int u: a) rasq.add(sta[u], fin[u], -1), trk[u]=false;
    }
    void process(int q) {
        while(q--)solve();
    }
};

// note group no necessary scc, as long as no ances.
void solve() {
    int n,q; cin >> n >> q;
    Tree tr(n); tr.process(q);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    return 0;
}

