		static auto s = get_sprite("czolg_body.bmp");
		static auto t = get_sprite("czolg_turret.bmp");
		auto& tank = dynamic_cast<Tank&>(e);
		disp.put_sprite_on_screen(s.get(), poz);
		double kat = std::arg(tank.turret_direction());
		if(kat < 0) kat += 2*pi;
