//##################################################################################################
PostSSAOLayer::~PostSSAOLayer()
{
  delete d;
}

//##################################################################################################
const PostSSAOParameters& PostSSAOLayer::parameters() const
{
  return d->parameters;
}

//##################################################################################################
void PostSSAOLayer::setParameters(const PostSSAOParameters& parameters)
{
  d->parameters = parameters;
