  rc = i2cBeginCyp(pI2C, iAddr, 0); // start a write operation: send slave address+write bit (0) 

  if (rc == 1) // slave sent ACK for its address
  {
     rc = i2cWriteCyp(pI2C, uRegister, 2); // write the register we want to read from
