	#endif
	// Block SIGPIPE before starting any other threads; other threads
	// created by main() will inherit a copy of the signal mask.
	ThreadSigPipeIng();
	const char *usage = "This is a v2 asr service.\n"
		"Usage: v2-asr-service [options] <nnet3-in> "
