    } else if (op == "SECSEEK") {
        return "SECSEEK " + get_native_register(dst) + " " + src1 + " r0";
    } else if (op == "PUBSEEK") {
        return "LW " + get_native_register(dst) + " " + get_native_register(dst) + " " + src1;
    } else if (op == "JMP" || op == "J") {
