        aAppli->SzW() = aSzW;
    }
    if (EAMIsInit(&distMax))
    {
        aAppli->DistMax() = distMax;
    }
    aAppli->WithImgLabel() = withLbl;
    aAppli->Reech() = 1.0/double(rech);
    aAppli->SetNameMesh(aMesh);
    aAppli->DoAllIm();


    return EXIT_SUCCESS;
}

