std::ostream& operator<<(std::ostream& os, const wxArrayString& arr)
{
    os << "[ ";
    for ( size_t n = 0; n < arr.size(); ++n )
    {
        if ( n )
            os << ", ";
        os << '"' << arr[n] << '"';
    }
    os << " ] (size=" << arr.size() << ")";
