    single<Nodes>().add(id, Endpoint{port, "127.0.0.1", Endpoint::Type::V4});
}

void broadcastTest()
{
    if (thisNode() == 1)
    {
        go([] {
            JLOG("broadcasting");
            broadcast([] {
                RJLOG("----- hello from node: " << thisNode());
            });
        });
    }
}

void replobTest()
{
    if (thisNode() != 1)
        return;
    go([] {
        single<Replob>().apply([] {
            RJLOG("--- commited for: " << thisNode());
            if (thisNode() != 2)
                return;
            single<Replob>().apply([] {
                RJLOG("--- commited from node 2 for: " << thisNode());
            });
        });
    });
}

int counter = 0;

void applyCounterAsync()
{
    go([] {
        single<Replob>().apply([] {
            ++ counter;
            if (thisNode() == 1)
            {
                applyCounterAsync();
            }
        });
    });
}

void perfTest()
{
    if (thisNode() == 1)
    {
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
        applyCounterAsync();
    }
    sleepFor(1000);
    RLOG("Counter: " << counter);
}

void consistencyTest()
{
    using L = std::vector<int>;
    static int val = 0;

    if (thisNode() <= 3)
    {
        for (int i = 0; i < 10; ++ i)
        go([] {
            NodeId src = thisNode();
            int v = val++;
            if (src == 3 && v == 5)
                sleepFor(1000);
            single<Replob>().apply([src, v] {
                single<L>().push_back(int(v*10 + src));
            });
        });
    }
    sleepFor(1000);
    int i = 0;
    //VERIFY(single<L>().size() == 1000, "Invalid size");
    for (int v: single<L>())
    {
        RJLOG("l[" << i++ << "] = " << v);
        //VERIFY(v == i++, "Invalid value");
    }
}

