		virtual std::shared_ptr<Buffer> CreateBuffer(const BufferType type, const uint64 size, const BufferMemoryProfile profile = BufferMemoryProfile::Automatic) = 0;

		/**
		 * Create a new image.
		 *
		 * @param type The image type.
