SwASCIIParser::SwASCIIParser( const SwASCIIParser& rSrc )
	: pDoc(rSrc.pDoc), pPam(0), rInput(rSrc.rInput), pArr(0),
		rOpt(rSrc.rOpt), pItemSet(0), nFileSize(rSrc.nFileSize),
		nScript(rSrc.nScript), bNewDoc(rSrc.bNewDoc)
{
	if( rSrc.pPam )
		pPam = new SwPaM( *rSrc.pPam->GetPoint() );
	if( rSrc.pArr )
	{
		pArr = new sal_Char [ ASC_BUFFLEN + 2 ];
		memcpy( pArr, rSrc.pArr, ASC_BUFFLEN + 2 );
	}
	if( rSrc.pItemSet )
		pItemSet = new SfxItemSet( *rSrc.pItemSet );

